  // ============================================
  // REAL-TIME QUOTES API - Unified pricing across all asset types
  // ============================================
  
  app.get("/api/realtime-quote/:symbol", async (req, res) => {
    try {
      const { symbol } = req.params;
      let assetType = (req.query.assetType as RTAssetType) || 'stock';

      // Auto-detect futures symbols (2-letter COMEX/NYMEX/CME codes)
      const FUTURES_SYMBOLS = ['ES', 'NQ', 'YM', 'RTY', 'MES', 'MNQ', 'CL', 'NG', 'RB', 'HO', 'BZ',
                               'GC', 'SI', 'HG', 'PL', 'PA', 'MGC', 'SIL', 'ZB', 'ZN', 'ZF', 'ZT',
                               'ZC', 'ZS', 'ZW', 'ZL', 'KC', 'CT', 'SB', 'CC', 'EC', 'JY', 'BP', 'AD',
                               '6E', '6J', '6B', 'VX'];
      const upperSymbol = symbol.toUpperCase();
      if (FUTURES_SYMBOLS.includes(upperSymbol) || upperSymbol.endsWith('=F')) {
        assetType = 'futures';
        // Use Yahoo Finance symbol format for futures
        const yahooSymbol = upperSymbol.endsWith('=F') ? upperSymbol : `${upperSymbol}=F`;
        const quote = await getRealtimeQuote(yahooSymbol, assetType);
        if (quote) {
          quote.symbol = upperSymbol; // Return original symbol without =F
          return res.json(quote);
        }
      }

      // Auto-detect crypto symbols
      const CRYPTO_SYMBOLS = ['BTC', 'ETH', 'SOL', 'XRP', 'ADA', 'DOGE', 'DOT', 'AVAX', 'LINK',
                              'MATIC', 'UNI', 'ATOM', 'LTC', 'FIL', 'NEAR', 'APT', 'ARB', 'OP', 'PEPE', 'SHIB'];
      if (CRYPTO_SYMBOLS.includes(upperSymbol)) {
        assetType = 'crypto';
      }

      const quote = await getRealtimeQuote(symbol, assetType);
      if (!quote) {
        return res.status(404).json({ error: "Quote not found" });
      }

      // Enrich with 52W data from Yahoo chart metadata (cheap call, has the data we need)
      if (assetType === 'stock' && !quote.fiftyTwoWeekHigh) {
        try {
          const yahooRes = await fetch(`https://query2.finance.yahoo.com/v8/finance/chart/${symbol}?range=1y&interval=1d`, {
            headers: { 'User-Agent': 'Mozilla/5.0' },
          });
          if (yahooRes.ok) {
            const yahooData = await yahooRes.json();
            const meta = yahooData?.chart?.result?.[0]?.meta;
            if (meta) {
              quote.fiftyTwoWeekHigh = meta.fiftyTwoWeekHigh || null;
              quote.fiftyTwoWeekLow = meta.fiftyTwoWeekLow || null;
              quote.averageVolume = meta.averageDailyVolume10Day || null;
              quote.previousClose = meta.chartPreviousClose || meta.previousClose || null;
              // Estimate market cap from price × shares if available
              if (meta.sharesOutstanding) {
                quote.marketCap = (quote.price || 0) * meta.sharesOutstanding;
              }
            }
          }
        } catch (e) {
          // Yahoo enrichment failed, continue without
        }
      }

      res.json(quote);
    } catch (error) {
      logger.error(`Error fetching realtime quote for ${req.params.symbol}:`, error);
      res.status(500).json({ error: "Failed to fetch quote" });
    }
  });
  
  app.post("/api/realtime-quotes/batch", async (req, res) => {
    try {
      const { requests } = req.body as { requests: Array<{ symbol: string; assetType: RTAssetType }> };
      
      if (!requests || !Array.isArray(requests)) {
        return res.status(400).json({ error: "Invalid request format. Expected { requests: [...] }" });
      }
      
      if (requests.length > 50) {
        return res.status(400).json({ error: "Maximum 50 quotes per batch request" });
      }
      
      const quotesMap = await getRealtimeBatchQuotes(requests);
      
      const quotes: Record<string, RealtimeQuote> = {};
      quotesMap.forEach((quote, key) => {
        quotes[key] = quote;
      });
      
      res.json({ quotes, count: Object.keys(quotes).length });
    } catch (error) {
      logger.error("Error fetching batch quotes:", error);
      res.status(500).json({ error: "Failed to fetch batch quotes" });
    }
  });

  // GET /api/historical-prices/:symbol - Get OHLC candle data for charts
  // Thin wrapper over server/historical-candles.ts. The body used to live inline
  // here, which meant in-process callers could only reach it by making an HTTP
  // request back into this same server — see the early-rotation fan-out. One
