  app.get("/api/convictions", requireBetaAccess, async (req: any, res) => {
    try {
      const { getCachedConvictions } = await import("./convictions-engine");
      const lookbackHours = req.query.lookbackHours ? Number(req.query.lookbackHours) : undefined;
      const limit = req.query.limit ? Number(req.query.limit) : undefined;
      const minScore = req.query.minScore ? Number(req.query.minScore) : undefined;
      const watchlistOnly = req.query.watchlistOnly === "false" ? false : true;
      const weeklyOnly = req.query.weeklyOnly === "true";
      const userId = req.session?.userId as string | undefined;
      // Optional ?symbol=AAPL filter — used by the idea-detail drawer so it
      // doesn't have to fetch the full picks payload to find one ticker.
      const symbolFilter = (req.query.symbol as string | undefined)?.toUpperCase();
      const directionFilter = (req.query.direction as string | undefined)?.toLowerCase();

      // When symbol-filtering, widen the build (don't watchlist-gate, raise
      // the minScore floor). Caller wants the score for ONE specific ticker;
      // if it's not in the approved list it should still come back.
      const buildOpts = symbolFilter
        ? {
            lookbackHours: lookbackHours ?? 96,
            limit: 500,
            minScore: 0,
            watchlistOnly: false,
            weeklyUserId: userId,
            weeklyOnly: false,
          }
        : {
            lookbackHours,
            limit,
            minScore,
            watchlistOnly,
            weeklyUserId: userId,
            weeklyOnly,
          };

      // Use the cached/shared snapshot so this endpoint and best-setups
      // always return matching scores for the same idea (single source of truth).
      let data = await getCachedConvictions(buildOpts);

      // Persist a sparse, auditable checkpoint for each live signal. This is
      // intentionally asynchronous: the screen should never wait on an audit
      // write, and the writer itself rate-limits each idea to one point / 15m.
      // The cockpit will only draw the points that made it into this table.
      void import('./signal-trajectory-service')
        .then(({ recordSignalTrajectory }) => recordSignalTrajectory(data.picks))
        .catch((err) => logger.warn('[TRAJECTORY] checkpoint write failed:', err));

      /**
       * Anything the bot HOLDS goes on the board, past every entry filter.
       *
       * See server/bot-held-picks.ts. Briefly: the cockpit was showing 4 of the
       * bot's 11 open positions, because held inventory was being re-judged by
       * the rules for opening a new position. NET was up $1,650 and invisible.
       *
       * Merged after the build so no gate above can remove them, and placed
       * first so inventory reads before candidates.
       */
      let picksWithHeld = data.picks;
      let botHeldCount = 0;
      try {
        const { getBotHeldPicks, mergeBotHeld } = await import("./bot-held-picks");
        const held = await getBotHeldPicks();
        botHeldCount = held.length;
        picksWithHeld = mergeBotHeld(data.picks, held) as typeof data.picks;
      } catch (err: any) {
        logger.warn(`[API] bot-held merge skipped: ${err?.message ?? err}`);
      }
      data = { ...data, picks: picksWithHeld };

      const meta = {
        _meta: {
          dataSource: "convictions_engine",
          cachedAt: new Date().toISOString(),
          picksCount: data.picks?.length ?? 0,
          botHeldCount,
        },
      };

      if (symbolFilter) {
        const filtered = data.picks.filter((p) => {
          if (p.symbol.toUpperCase() !== symbolFilter) return false;
          if (directionFilter && p.direction.toLowerCase() !== directionFilter) return false;
          return true;
        });
        res.json({ ...data, picks: filtered, ...meta });
        return;
      }

      res.json({ ...data, ...meta });
    } catch (error) {
      logger.error("[API] Convictions error:", error);
      res.status(500).json({ error: "Failed to build convictions" });
    }
  });

