  // ═══════════════════════════════════════════════════════════════
  // PRE-MARKET GAPPERS — overnight movers from weekly + approved tickers
  // ═══════════════════════════════════════════════════════════════

  app.get("/api/premarket/gappers", requireBetaAccess, async (req: any, res) => {
    try {
      const { getPreMarketBatch, currentMarketPhase } = await import("./pre-market-service");
      const minGapPct = req.query.minGapPct ? Number(req.query.minGapPct) : 1;
      const userId = req.session?.userId as string | undefined;

      // Symbol universe: weekly watchlist (priority) + approved tickers fallback
      const symbols = new Set<string>();
      let weeklySymbols: Set<string> = new Set();
      if (userId) {
        try {
          const { getWeeklyWatchlist } = await import("./weekly-watchlist-seeder");
          const items = await getWeeklyWatchlist(userId);
          items.forEach((i: any) => {
            const s = i.symbol.toUpperCase();
            symbols.add(s);
            weeklySymbols.add(s);
          });
        } catch (err) {
          logger.debug("[API] gappers: weekly fetch failed", err);
        }
      }
      try {
        const { APPROVED_TICKERS } = await import("@shared/approved-tickers");
        APPROVED_TICKERS.forEach((sym) => symbols.add(sym.toUpperCase()));
      } catch (err) {
        logger.debug("[API] gappers: approved tickers import failed", err);
      }
      // Hard cap so the Yahoo batch doesn't explode
      const symbolArr = Array.from(symbols).slice(0, 80);
      if (symbolArr.length === 0) {
        return res.json({ phase: currentMarketPhase(), gappers: [], scanned: 0 });
      }

      const snaps = await getPreMarketBatch(symbolArr);
      const gappers = Array.from(snaps.values())
        .filter((s) => Number.isFinite(s.gapPct) && Math.abs(s.gapPct) >= minGapPct)
        .map((s) => ({
          symbol: s.symbol,
          price: s.price,
          previousClose: s.previousClose,
          gapPct: Number(s.gapPct.toFixed(2)),
          direction: s.gapDirection,
          phase: s.phase,
          isWeekly: weeklySymbols.has(s.symbol),
        }))
        .sort((a, b) => Math.abs(b.gapPct) - Math.abs(a.gapPct));

      res.json({
        phase: currentMarketPhase(),
        scanned: snaps.size,
        gappers,
        generatedAt: new Date().toISOString(),
      });
    } catch (error) {
      logger.error("[API] Pre-market gappers error:", error);
      res.status(500).json({ error: "Failed to fetch pre-market gappers" });
    }
  });

  // ═══════════════════════════════════════════════════════════════
  // MARKET PROJECTOR — Next session outlook with probability zones
  // ═══════════════════════════════════════════════════════════════

  app.get("/api/projector", requireBetaAccess, async (req: any, res) => {
    try {
      const { getCachedProjectorData } = await import("./market-projector");
      const timeframe = (req.query.timeframe as string) === 'weekly' ? 'weekly' : 'daily';
      const data = await getCachedProjectorData(timeframe);
      res.json(data);
    } catch (error) {
      logger.error("[API] Projector error:", error);
      res.status(500).json({ error: "Failed to compute projection" });
    }
  });

  // ═══════════════════════════════════════════════════════════════
  // FLOW EDGE - Options flow scanner (Algo Edge equivalent)
  // ═══════════════════════════════════════════════════════════════

  app.get("/api/options-flow", requireBetaAccess, async (req: any, res) => {
    try {
      const { getOptionsFlow } = await import("./flow-edge-service");
      const result = await getOptionsFlow({
        symbol: req.query.symbol as string,
        flowType: req.query.flowType as string,
        minPremium: req.query.minPremium ? parseFloat(req.query.minPremium) : undefined,
        strategyCategory: req.query.strategyCategory as string,
        dteCategory: req.query.dteCategory as string,
        sentiment: req.query.sentiment as string,
        limit: parseInt(req.query.limit as string) || 50,
        offset: parseInt(req.query.offset as string) || 0,
        days: parseInt(req.query.days as string) || 7,
      });
      res.json(result);
    } catch (error) {
      logger.error("[API] Failed to fetch options flow:", error);
      res.status(500).json({ error: "Failed to fetch options flow" });
    }
  });

  // Flow-GEX Convergence for a specific symbol
  app.get("/api/flow-gex-convergence/top", requireBetaAccess, async (req: any, res) => {
    try {
      const { getTopConvergenceSignals } = await import("./flow-gex-convergence");
      const limit = Math.min(parseInt(req.query.limit as string) || 5, 10);
      const signals = await getTopConvergenceSignals(limit);
      res.json({ signals, timestamp: new Date().toISOString() });
    } catch (error) {
      logger.error("[API] Failed to fetch top convergence signals:", error);
      res.status(500).json({ error: "Failed to fetch convergence signals" });
    }
  });

  app.get("/api/flow-gex-convergence/:symbol", requireBetaAccess, async (req: any, res) => {
    try {
      const { computeConvergenceSignal } = await import("./flow-gex-convergence");
      const signal = await computeConvergenceSignal(req.params.symbol);
      if (!signal) {
        return res.json({ signal: null, message: "No convergence data available" });
      }
      res.json({ signal });
    } catch (error) {
      logger.error("[API] Failed to compute convergence signal:", error);
      res.status(500).json({ error: "Failed to compute convergence signal" });
    }
  });

  // 🎯 BEST SETUPS - Top 5 conviction plays for daily/weekly view
  // Forces discipline: wait for the perfect pitch instead of swinging at everything
  // Now supports status filtering (all, open, hit_target, stopped_out, expired)
  // And date filtering (specific date in YYYY-MM-DD format)
  app.get("/api/trade-ideas/best-setups", async (req: any, res) => {
    try {
      const period = req.query.period as string || 'daily'; // 'daily' or 'weekly'
      const limit = Math.min(parseInt(req.query.limit as string) || 5, 2000); // Allow up to 2000 ideas
      const statusFilter = req.query.status as string || 'open'; // 'all', 'open', 'hit_target', 'hit_stop', 'expired'
      const dateFilter = req.query.date as string; // 'today', 'week', or 'YYYY-MM-DD'
      const symbolFilter = req.query.symbol as string; // Optional: filter by specific symbol
      const watchlistOnly = req.query.watchlistOnly === 'true'; // Only show ideas for user's watchlist symbols

      // 🔍 DEBUG: Log incoming request params
      logger.info(`[BEST-SETUPS] 📥 REQUEST - date: '${dateFilter}', status: '${statusFilter}', limit: ${limit}, watchlistOnly: ${watchlistOnly}`);

      // OPTIMIZATION: Use getRecentTradeIdeas with appropriate time window
      // Expand time window if viewing closed trades or specific date
      const needsAllData = statusFilter !== 'open' || dateFilter;
      const hoursBack = needsAllData ? 720 : (period === 'daily' ? 48 : 168); // 30 days for history, otherwise 2-7 days
      const allIdeasRaw = await storage.getRecentTradeIdeas(hoursBack, needsAllData ? 5000 : 2000);
      // Filter out archived ideas from UI (but they stay in DB for calibration training)
      const allIdeas = allIdeasRaw.filter((i: any) => !i.archived);
      const now = new Date();

      // DEBUG: Log total ideas and field presence
      logger.info(`[BEST-SETUPS] Recent ideas (${hoursBack}h): ${allIdeas.length}, statusFilter: ${statusFilter}, dateFilter: ${dateFilter || 'none'}`);
      const openStatusCount = allIdeas.filter(i => i.outcomeStatus === 'open' || !i.outcomeStatus).length;
      const closedCount = allIdeas.filter(i => i.outcomeStatus && i.outcomeStatus !== 'open').length;
      logger.info(`[BEST-SETUPS] Status breakdown: ${openStatusCount} open, ${closedCount} closed`);

      // Apply status filter
      let filteredIdeas = allIdeas.filter(i => {
        if (statusFilter === 'all') return true;
        if (statusFilter === 'open') return i.outcomeStatus === 'open' || !i.outcomeStatus;
        if (statusFilter === 'closed') return i.outcomeStatus === 'hit_target' || i.outcomeStatus === 'hit_stop' || i.outcomeStatus === 'expired';
        return i.outcomeStatus === statusFilter;
      });

      // 🎯 WATCHLIST FILTER: Only show ideas for symbols the user actually watches.
      // Without this, Trade Desk shows 772+ ideas from the entire scanner universe.
      // The user's watchlist is their curated focus list — Trade Desk should respect it.
      if (watchlistOnly) {
        const sessionUserId = req.session?.userId;
        let watchlistSyms = new Set<string>();

        // Mirror the same logic as GET /api/watchlist: admin sees all, users see their own
        const adminEmail = process.env.ADMIN_EMAIL || "";
        let isAdmin = false;
        if (sessionUserId) {
          const user = await storage.getUser(sessionUserId);
          isAdmin = adminEmail !== "" && user?.email === adminEmail;
        }

        if (isAdmin || !sessionUserId) {
          // Admin or unauthenticated — use full watchlist
          const allWl = await storage.getAllWatchlist();
          for (const item of allWl) {
            watchlistSyms.add((item.symbol || '').toUpperCase());
          }
        } else {
          // Regular user — their personal watchlist only
          const userWl = await storage.getWatchlistByUser(sessionUserId);
          for (const item of userWl) {
            watchlistSyms.add((item.symbol || '').toUpperCase());
          }
        }
        // Also include the weekly focus list (curated each Monday)
        try {
          const { getCurrentWeekSymbols } = await import('./weekly-watchlist-seeder');
          const weeklySyms = await getCurrentWeekSymbols();
          for (const sym of weeklySyms) watchlistSyms.add(sym.toUpperCase());
        } catch { /* weekly seeder not available */ }
        const beforeWl = filteredIdeas.length;
        filteredIdeas = filteredIdeas.filter(i => watchlistSyms.has((i.symbol || '').toUpperCase()));
        logger.info(`[BEST-SETUPS] Watchlist filter: ${beforeWl} -> ${filteredIdeas.length} ideas (${watchlistSyms.size} watchlist symbols)`);
      }

      // Apply date filter if specified (supports 'today', 'week', or 'YYYY-MM-DD')
      if (dateFilter) {
        // Get today's date in ET timezone
        const nowET = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/New_York' }));
        const todayStr = `${nowET.getFullYear()}-${String(nowET.getMonth() + 1).padStart(2, '0')}-${String(nowET.getDate()).padStart(2, '0')}`;

        logger.info(`[BEST-SETUPS] Date filter requested: '${dateFilter}', today in ET: '${todayStr}'`);

        const beforeFilter = filteredIdeas.length;

        if (dateFilter === 'today') {
          // Only today's ideas - properly convert UTC timestamps to ET for comparison
          logger.info(`[BEST-SETUPS] 🔍 TODAY FILTER ACTIVE - filtering ${filteredIdeas.length} ideas`);

          if (filteredIdeas.length > 0) {
            // Log sample timestamps with their ET conversions
            const samples = filteredIdeas.slice(0, 5).map(i => {
              const utc = new Date(i.timestamp || '');
              const etDate = utc.toLocaleDateString('en-CA', { timeZone: 'America/New_York' });
              return `${i.symbol}: ${i.timestamp} -> ET: ${etDate}`;
            });
            logger.info(`[BEST-SETUPS] Sample conversions:\n${samples.join('\n')}`);
          }

          // Convert each idea's UTC timestamp to ET date and compare
          const beforeCount = filteredIdeas.length;
          filteredIdeas = filteredIdeas.filter(i => {
            if (!i.timestamp) {
              logger.debug(`[BEST-SETUPS] Idea ${i.symbol} has no timestamp - excluding`);
              return false;
            }
            try {
              // Parse UTC timestamp and convert to ET
              const ideaDateUTC = new Date(i.timestamp);
              // Get the date string in ET timezone
              const ideaDateStrET = ideaDateUTC.toLocaleDateString('en-CA', { timeZone: 'America/New_York' }); // 'en-CA' gives YYYY-MM-DD format
              const matches = ideaDateStrET === todayStr;
              if (!matches) {
                logger.debug(`[BEST-SETUPS] EXCLUDING ${i.symbol}: date ${ideaDateStrET} != today ${todayStr}`);
              }
              return matches;
            } catch (err) {
              logger.error(`[BEST-SETUPS] Error parsing timestamp for ${i.symbol}: ${err}`);
              return false;
            }
          });

          logger.info(`[BEST-SETUPS] Today filter result: ${beforeCount} -> ${filteredIdeas.length} ideas (comparing against '${todayStr}' ET)`);
        } else if (dateFilter === 'week') {
          // Last 7 days
          const weekAgo = new Date(nowET.getTime() - 7 * 24 * 60 * 60 * 1000);
          filteredIdeas = filteredIdeas.filter(i => i.timestamp && new Date(i.timestamp) >= weekAgo);
        } else if (/^\d{4}-\d{2}-\d{2}$/.test(dateFilter)) {
          // Specific date (YYYY-MM-DD format)
          filteredIdeas = filteredIdeas.filter(i => i.timestamp && i.timestamp.startsWith(dateFilter));
        }

        logger.info(`[BEST-SETUPS] After date filter '${dateFilter}': ${beforeFilter} -> ${filteredIdeas.length} ideas`);

        // 🚀 AUTO-GENERATE: If "today" filter returns 0 ideas during market hours, trigger background generation
        // This ensures fresh ideas are always available even if scheduled windows were missed
        if (dateFilter === 'today' && filteredIdeas.length === 0) {
          const nowET = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/New_York' }));
          const etHour = nowET.getHours();
          const dayOfWeek = nowET.getDay(); // 0=Sun, 6=Sat

          // Only auto-generate during weekdays (Mon-Fri) between 8am-9pm ET
          const isWeekday = dayOfWeek >= 1 && dayOfWeek <= 5;
          const isDuringTradingHours = etHour >= 8 && etHour <= 21;

          if (isWeekday && isDuringTradingHours) {
            logger.info(`[BEST-SETUPS] No ideas for today - triggering background generation...`);
            // Don't await - generate in background so response isn't delayed
            (await getAutoIdeaGenerator()).forceGenerate(false, false).catch(err => {
              logger.error('[BEST-SETUPS] Background generation failed:', err);
            });
          }
        }
      }

      // Apply symbol filter if specified (for single stock lookups)
      if (symbolFilter) {
        filteredIdeas = filteredIdeas.filter(i => i.symbol?.toUpperCase() === symbolFilter.toUpperCase());
        logger.info(`[BEST-SETUPS] After symbol filter (${symbolFilter}): ${filteredIdeas.length} ideas`);
      }

      // Filter to ideas with complete price data
      let openIdeas = filteredIdeas.filter(i =>
        i.entryPrice && i.targetPrice && i.stopLoss
      );
      logger.info(`[BEST-SETUPS] After prices filter: ${openIdeas.length} ideas`);
      
      // 🎯 TRACK EARLIEST TIMESTAMPS before deconfliction (so we don't lose early signals)
      // Key: symbol:assetType:optionType -> earliest timestamp
      const symbolFirstTimestamp = new Map<string, string>();
      for (const idea of openIdeas) {
        const assetType = idea.assetType || 'stock';
        const optionType = idea.optionType || '';
        const key = `${idea.symbol}:${assetType}:${optionType}`;
        
        const ideaTime = idea.timestamp ? new Date(idea.timestamp).getTime() : Infinity;
        const existingFirstTime = symbolFirstTimestamp.get(key);
        if (!existingFirstTime || ideaTime < new Date(existingFirstTime).getTime()) {
          symbolFirstTimestamp.set(key, idea.timestamp || '');
        }
      }
      
      // 🎯 RELIABILITY FILTER: Remove conflicting directional signals for Best Setups
      // Only show the strongest directional conviction per symbol
      const symbolGroups = new Map<string, typeof openIdeas>();
      for (const idea of openIdeas) {
        if (!symbolGroups.has(idea.symbol)) {
          symbolGroups.set(idea.symbol, []);
        }
        symbolGroups.get(idea.symbol)!.push(idea);
      }
      
      const deconflictedIdeas: typeof openIdeas = [];
      for (const [symbol, symbolIdeas] of symbolGroups) {
        const isLongIdea = (i: any) => (i.direction || '').toLowerCase() === 'long' || i.optionType === 'call';
        const isShortIdea = (i: any) => (i.direction || '').toLowerCase() === 'short' || i.optionType === 'put';
        const hasLong = symbolIdeas.some(isLongIdea);
        const hasShort = symbolIdeas.some(isShortIdea);
        
        if (hasLong && hasShort) {
          const longIdeas = symbolIdeas.filter(isLongIdea);
          const shortIdeas = symbolIdeas.filter(isShortIdea);
          const maxLongConf = Math.max(...longIdeas.map(i => i.confidenceScore || 0));
          const maxShortConf = Math.max(...shortIdeas.map(i => i.confidenceScore || 0));
          
          if (maxLongConf >= maxShortConf + 10) {
            deconflictedIdeas.push(...longIdeas);
          } else if (maxShortConf >= maxLongConf + 10) {
            deconflictedIdeas.push(...shortIdeas);
          } else {
            // Keep the BEST of each direction instead of dropping both
            const bestLong = longIdeas.sort((a, b) => (b.confidenceScore || 0) - (a.confidenceScore || 0))[0];
            const bestShort = shortIdeas.sort((a, b) => (b.confidenceScore || 0) - (a.confidenceScore || 0))[0];
            if (bestLong) deconflictedIdeas.push(bestLong);
            if (bestShort) deconflictedIdeas.push(bestShort);
          }
        } else {
          deconflictedIdeas.push(...symbolIdeas);
        }
      }
      openIdeas = deconflictedIdeas;
      
      // 🎯 RELIABILITY FILTER: Minimum confidence for all trade ideas
      const MIN_OPTIONS_CONFIDENCE_BEST = 65;
      const MIN_STOCK_CONFIDENCE_BEST = 60;
      openIdeas = openIdeas.filter(idea => {
        const score = idea.confidenceScore || 0;
        if (idea.assetType === 'option' || idea.optionType) {
          return score >= MIN_OPTIONS_CONFIDENCE_BEST;
        }
        return score >= MIN_STOCK_CONFIDENCE_BEST;
      });
      
      // Apply time filter based on period using multiple timestamp sources
      // SKIP if date filter already applied (date filter is more precise than rolling windows)
      // Priority: timestamp > entryValidUntil > exitBy (fallback to showing all open if no dates)
      const getIdeaDate = (idea: any): Date | null => {
        if (idea.timestamp) return new Date(idea.timestamp);
        if (idea.createdAt) return new Date(idea.createdAt);
        return null;
      };

      // Only apply period filter if NO date filter was specified
      // Date filter (today/week/specific date) takes precedence over rolling period windows
      if (!dateFilter) {
        if (period === 'daily') {
          // Ideas from last 24 hours - STRICT filtering, no date = no show
          const oneDayAgo = new Date(now.getTime() - 24 * 60 * 60 * 1000);
          openIdeas = openIdeas.filter(i => {
            const ideaDate = getIdeaDate(i);
            // MUST have a timestamp - don't show ideas with no date
            if (!ideaDate) return false;
            const entryValidUntil = i.entryValidUntil ? new Date(i.entryValidUntil) : null;
            // Include if: recent creation/timestamp OR entry still valid
            return ideaDate >= oneDayAgo || (entryValidUntil && entryValidUntil >= now);
          });
        } else if (period === 'weekly') {
          // Ideas from last 3 days (tightened from 7) - keep it fresh
          const threeDaysAgo = new Date(now.getTime() - 3 * 24 * 60 * 60 * 1000);
          openIdeas = openIdeas.filter(i => {
            const ideaDate = getIdeaDate(i);
            // MUST have a timestamp - don't show ideas with no date
            if (!ideaDate) return false;
            const entryValidUntil = i.entryValidUntil ? new Date(i.entryValidUntil) : null;
            // Include if: recent OR entry still valid
            return ideaDate >= threeDaysAgo || (entryValidUntil && entryValidUntil >= now);
          });
        }
      } else {
        logger.info(`[BEST-SETUPS] Skipping period filter - date filter '${dateFilter}' already applied`);
      }
      
      // PERFORMANCE OPTIMIZATION: Pre-filter to tradeable-quality ideas.
      // An idea qualifies if EITHER:
      //   (a) it has a tradeable letter grade (probabilityBand A+..D+), OR
      //   (b) it has no grade but a confidence score ≥ 50 (the convictions
      //       engine, surge scanners, and several other ingestion paths
      //       create ideas WITHOUT setting probabilityBand — those used to
      //       be silently dropped here, which was the root cause of the
      //       Trade Desk showing only 1 idea even though dozens were live).
      const TRADEABLE_GRADES = new Set([
        'A+', 'A', 'A-', 'B+', 'B', 'B-', 'C+', 'C', 'C-', 'D+',
      ]);
      const highGradeIdeas = openIdeas.filter((i) => {
        const grade = (i.probabilityBand || '').trim();
        if (grade && TRADEABLE_GRADES.has(grade)) return true;
        // Ungraded path — accept if confidence is plausible
        if (!grade && (i.confidenceScore ?? 0) >= 50) return true;
        return false;
      });
      logger.info(
        `[BEST-SETUPS] Quality filter: ${highGradeIdeas.length} ideas (graded + ungraded ≥50 confidence)`,
      );

      // Fallback: if fewer than limit qualifying ideas, include all open ideas
      const candidateIdeas = highGradeIdeas.length >= limit
        ? highGradeIdeas
        : openIdeas.slice(0, 100);

      logger.info(`[BEST-SETUPS] Grade distribution: ${JSON.stringify(
        openIdeas.reduce((acc, i) => {
          const g = i.probabilityBand || 'none';
          acc[g] = (acc[g] || 0) + 1;
          return acc;
        }, {} as Record<string, number>)
      )}`);
      
      logger.info(`[BEST-SETUPS] Pre-filtered to ${candidateIdeas.length} candidates (from ${openIdeas.length} open ideas)`);
      
      // Calculate historical win rate by symbol (from all closed trade ideas)
      // Uses actual outcome statuses: 'hit_target', 'stopped_out', 'expired'
      const calculateSymbolWinRate = (symbol: string): { winRate: number; sampleSize: number } => {
        const symbolIdeas = allIdeas.filter(i => 
          i.symbol === symbol && 
          (i.outcomeStatus === 'hit_target' || i.outcomeStatus === 'stopped_out' || i.outcomeStatus === 'expired')
        );
        if (symbolIdeas.length < 3) return { winRate: 50, sampleSize: symbolIdeas.length };
        const wins = symbolIdeas.filter(i => i.outcomeStatus === 'hit_target').length;
        return { winRate: Math.round((wins / symbolIdeas.length) * 100), sampleSize: symbolIdeas.length };
      };
      
      // Fast scoring without ML/breakout calls (skip expensive async operations)
      // ⚠️ H9: this is the in-route RANKING score, used only to pick which
      // ideas get enriched + returned. It is NOT the canonical convictionScore
      // that the UI displays — that one comes from the convictions engine and
      // is enriched on top of these survivors below. Naming it `rankingScore`
      // here so it doesn't shadow the canonical field.
      const scoredIdeas = candidateIdeas.map(idea => {
        const confidence = idea.confidenceScore || 50;
        const signalCount = idea.qualitySignals?.length || 0;
        const riskReward = idea.targetPrice && idea.entryPrice && idea.stopLoss
          ? (idea.targetPrice - idea.entryPrice) / Math.max(0.01, idea.entryPrice - idea.stopLoss)
          : 1;

        // Base ranking score
        let rankingScore = confidence;

        // 🔥 SOURCE PRIORITY BONUS - Prioritize momentum/surge over generic options flow
        // This ensures we show IREN/ONDS/RDW surges instead of random options flow on slow stocks
        const dataSource = idea.dataSourceUsed || '';
        const ideaSource = idea.source || '';
        const sourcePriority: Record<string, number> = {
          'surge_detection': 25,       // Highest priority - real-time momentum
          'spx_session': 22,           // Index session scanner - real-time intraday signals
          'orb_scanner': 22,           // ORB breakout scanner - time-critical
          'market_scanner': 20,        // Market movers (top gainers)
          'bullish_trend': 18,         // Confirmed trends
          'breakout_discovery': 18,    // Breakout patterns
          'quant_signal': 15,          // Quantitative signals
          'news_catalyst': 12,         // News-driven
          'options_flow': 8,           // Options flow - lower priority (can be noise)
          'social_sentiment': 5,       // Social - speculative
        };
        // Check both source fields — idea.source (e.g. 'spx_session') and dataSourceUsed (e.g. 'surge_detection')
        const sourceBonus = Math.max(
          sourcePriority[ideaSource] || 0,
          sourcePriority[dataSource] || 0,
          10  // minimum default
        );
        rankingScore += sourceBonus;

        // Signal confluence bonus (more signals = higher rank)
        rankingScore += signalCount * 5;

        // 🎯 ASSET TYPE - Give OPTIONS a SLIGHT boost for visibility
        // Options require timely action due to expiration, show them prominently
        const assetType = idea.assetType || '';
        if (assetType === 'stock') {
          rankingScore += 5; // Small boost for stocks
        } else if (assetType === 'option') {
          rankingScore += 10; // Options get priority - they expire!
        }

        // Risk/Reward bonus (capped at 3:1 for max bonus)
        rankingScore += Math.min(riskReward, 3) * 10;

        // Grade bonus
        const grade = idea.probabilityBand || '';
        if (grade === 'A+' || grade === 'A') rankingScore += 10;
        else if (grade === 'A-' || grade === 'B+') rankingScore += 5;

        // Historical win rate bonus (fast, no API calls)
        const { winRate, sampleSize } = calculateSymbolWinRate(idea.symbol);
        let winRateBonus = 0;
        if (sampleSize >= 5) {
          if (winRate >= 70) winRateBonus = 15;
          else if (winRate >= 60) winRateBonus = 10;
          else if (winRate >= 50) winRateBonus = 5;
          else if (winRate < 40) winRateBonus = -10;
        }
        rankingScore += winRateBonus;

        // Freshness scoring — newer ideas rank higher
        const ideaTimestamp = idea.timestamp ? new Date(idea.timestamp).getTime() : Date.now();
        const ideaAgeHours = (Date.now() - ideaTimestamp) / (1000 * 60 * 60);
        let freshnessBonus = 0;
        if (ideaAgeHours < 1) freshnessBonus = 10;
        else if (ideaAgeHours < 3) freshnessBonus = 5;
        else if (ideaAgeHours > 6) freshnessBonus = -15;
        else if (ideaAgeHours > 12) freshnessBonus = -25;
        rankingScore += freshnessBonus;

        return {
          ...idea,
          rankingScore: Math.round(Math.max(rankingScore, 0)),
          signalCount,
          riskReward: Math.round(riskReward * 100) / 100,
          mlDirection: 'neutral',  // Skip slow ML calls for performance
          mlBoost: 0,
          hourlyConfirmed: false,
          breakoutBonus: 0,
          historicalWinRate: winRate,
          historicalSampleSize: sampleSize,
          winRateBonus,
          freshnessBonus,
          ideaAgeHours: Math.round(ideaAgeHours * 10) / 10,
          sourceBonus,  // Track source priority bonus for debugging
          source: ideaSource || dataSource,  // Include source for transparency
          confidence
        };
      });
      
      // Sort by ranking score descending (this is in-route ranking, not the
      // canonical conviction score — that gets enriched on top further down).
      scoredIdeas.sort((a, b) => b.rankingScore - a.rankingScore);
      
      // 🎯 CRITICAL: Deduplicate by symbol+assetType+optionType - keep BEST setup per unique combo
      // This allows showing DIS CALL and DIS PUT as separate entries
      // Scanner sources (spx_session, orb_scanner) get their own slot so they don't compete with flow ideas
      const INDEX_SCANNER_SOURCES = new Set(['spx_session', 'orb_scanner']);
      const symbolBestMap = new Map<string, typeof scoredIdeas[0]>();

      for (const idea of scoredIdeas) {
        const assetType = idea.assetType || 'stock';
        const optionType = idea.optionType || '';  // Include call/put distinction
        const ideaSource = idea.source || idea.dataSourceUsed || '';
        // Index scanner ideas get their own dedup slot so they surface alongside flow ideas
        const sourceTag = INDEX_SCANNER_SOURCES.has(ideaSource) ? `:${ideaSource}` : '';
        const key = `${idea.symbol}:${assetType}:${optionType}${sourceTag}`;
        const existing = symbolBestMap.get(key);

        // Keep the one with higher conviction (first one wins since already sorted)
        if (!existing) {
          symbolBestMap.set(key, idea);
        }
      }
      
      // Attach the EARLIEST timestamp (tracked before deconfliction) as 'firstGeneratedAt'
      for (const [key, idea] of symbolBestMap) {
        const firstTs = symbolFirstTimestamp.get(key);
        if (firstTs) {
          (idea as any).firstGeneratedAt = firstTs;
        }
      }
      
      // Convert map back to array and re-sort (map doesn't preserve order)
      const uniqueBySymbol = Array.from(symbolBestMap.values());
      uniqueBySymbol.sort((a, b) => b.rankingScore - a.rankingScore);

      // Oversample 3× so the convictions enrichment + re-rank below has
      // headroom — final slice to `limit` happens after re-ranking by the
      // canonical convictions score.
      const oversampleLimit = Math.max(limit * 3, 30);
      let topSetups = uniqueBySymbol.slice(0, oversampleLimit);

      // 🛡️ FINAL SAFETY CHECK: If date filter is 'today', do one last verification
      // This catches any ideas that might have slipped through earlier filters
      if (dateFilter === 'today') {
        const nowET = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/New_York' }));
        const todayStrFinal = `${nowET.getFullYear()}-${String(nowET.getMonth() + 1).padStart(2, '0')}-${String(nowET.getDate()).padStart(2, '0')}`;

        const beforeFinalFilter = topSetups.length;
        topSetups = topSetups.filter(s => {
          if (!s.timestamp) return false;
          const ideaDateET = new Date(s.timestamp).toLocaleDateString('en-CA', { timeZone: 'America/New_York' });
          return ideaDateET === todayStrFinal;
        });

        if (beforeFinalFilter !== topSetups.length) {
          logger.warn(`[BEST-SETUPS] ⚠️ FINAL SAFETY: Removed ${beforeFinalFilter - topSetups.length} non-today ideas that slipped through!`);
        }
      }

      // 🛡️ PHASE 1 REVALIDATION — applies the same age cap, catalyst-vs-direction
      // contradiction reject, and live-price-vs-stop/target checks the convictions
      // engine uses. Fixes the "stale ideas + chase entries" bug at the API layer
      // so all 12+ downstream consumers (Top Convictions widget, high-conviction-alert,
      // home, landing, stock-detail, etc.) get clean data automatically.
      let revalidationDiagnostics: { rejected: number; ageRejected: number; liveRejected: number } = {
        rejected: 0,
        ageRejected: 0,
        liveRejected: 0,
      };
      try {
        const { revalidateBestSetups } = await import('./convictions-engine');
        const { kept, diagnostics } = await revalidateBestSetups(topSetups);
        revalidationDiagnostics = {
          rejected: diagnostics.ageRejected + diagnostics.liveRejected,
          ageRejected: diagnostics.ageRejected,
          liveRejected: diagnostics.liveRejected,
        };
        topSetups = kept;
      } catch (revErr) {
        logger.warn(`[BEST-SETUPS] revalidation failed (returning unfiltered): ${(revErr as Error).message}`);
      }

      // 🎯 H1 + H7: Enrich every survivor with the canonical convictions-engine
      // score / band / layers, then re-rank and final-slice. This collapses the
      // two parallel scoring pipelines (in-route formula vs. layered engine)
      // into one — so the desk page sidebar, drawer, Top Conviction widget,
      // and high-conviction alerts all show the same number for the same idea.
      // Cached for 60s (CONVICTIONS_CACHE_TTL_MS) so polling consumers don't
      // pay full cost on every request.
      let enrichedCount = 0;
      try {
        const { getCachedConvictions } = await import('./convictions-engine');
        const sessionUserId = (req.session as any)?.userId as string | undefined;
        const convData = await getCachedConvictions({
          lookbackHours: 96,
          limit: 500,
          watchlistOnly: false,
          minScore: 0,
          weeklyUserId: sessionUserId,
        });
        const pickByKey = new Map<string, any>();
        for (const p of convData.picks) {
          // Index by symbol+direction (the natural key) AND symbol-only as
          // a fallback for ideas where direction may be inferred differently.
          const dir = (p.direction || 'long').toLowerCase();
          pickByKey.set(`${p.symbol}::${dir}`, p);
          if (!pickByKey.has(p.symbol)) pickByKey.set(p.symbol, p);
        }
        topSetups = topSetups.map((s: any) => {
          const dir = (s.direction || 'long').toLowerCase();
          const pick = pickByKey.get(`${s.symbol}::${dir}`) || pickByKey.get(s.symbol);
          if (pick) {
            enrichedCount++;
            return {
              ...s,
              convictionScore: pick.convictionScore,
              convictionBand: pick.convictionBand,
              layers: pick.layers,
              layerCount: pick.layerCount,
              // Prefer the engine's thesis but fall back to scanner thesis
              thesis: pick.thesis || s.thesis || s.analysis,
            };
          }
          return s;
        });
        // Re-rank by the canonical conviction score
        topSetups.sort((a: any, b: any) => (b.convictionScore || 0) - (a.convictionScore || 0));
      } catch (enrichErr) {
        logger.warn(`[BEST-SETUPS] convictions enrichment failed (using in-route scores): ${(enrichErr as Error).message}`);
      }

      // Final slice to the originally-requested limit (after enrichment + re-rank)
      topSetups = topSetups.slice(0, limit);

      // Conflict detection: flag tickers that appear with opposing directions
      // (e.g. AAPL LONG from breakout scanner + AAPL SHORT from bearish scanner)
      const directionsBySymbol = new Map<string, Set<string>>();
      for (const s of topSetups) {
        const dir = (s.direction || 'long').toLowerCase();
        if (!directionsBySymbol.has(s.symbol)) directionsBySymbol.set(s.symbol, new Set());
        directionsBySymbol.get(s.symbol)!.add(dir);
      }
      const conflictSymbols: string[] = [];
      directionsBySymbol.forEach((dirs, sym) => {
        if (dirs.size > 1) conflictSymbols.push(sym);
      });
      if (conflictSymbols.length > 0) {
        // Tag each conflicting setup so the UI can display a warning
        topSetups = topSetups.map((s: any) => {
          if (conflictSymbols.includes(s.symbol)) {
            return { ...s, hasDirectionConflict: true };
          }
          return s;
        });
        logger.warn(`[BEST-SETUPS] ⚠️ Direction conflicts detected: ${conflictSymbols.join(', ')}`);
      }

      logger.info(`[BEST-SETUPS] Returning ${topSetups.length} top setups for ${period} (from ${openIdeas.length} open ideas, freshness-rejected ${revalidationDiagnostics.rejected}, convictions-enriched ${enrichedCount}, conflicts: ${conflictSymbols.length})`);

      // 🔍 DEBUG: Log the dates of returned setups to verify filtering
      if (topSetups.length > 0) {
        const setupDates = topSetups.slice(0, 10).map(s => {
          const ts = s.timestamp;
          if (!ts) return `${s.symbol}: NO_TIMESTAMP`;
          const utc = new Date(ts);
          const etDate = utc.toLocaleDateString('en-CA', { timeZone: 'America/New_York' });
          return `${s.symbol}: ${etDate}`;
        });
        logger.info(`[BEST-SETUPS] 📤 RESPONSE dates (first 10): ${setupDates.join(', ')}`);
      }

      res.json({
        period,
        count: topSetups.length,
        totalOpen: openIdeas.length,
        setups: topSetups,
        generatedAt: now.toISOString(),
        revalidation: revalidationDiagnostics,
        conflicts: conflictSymbols,
        _meta: {
          dataSource: "trade_ideas_db + convictions_engine",
          cachedAt: now.toISOString(),
        },
      });
    } catch (error) {
      logger.error('[BEST-SETUPS] Error:', error);
      res.status(500).json({ error: "Failed to fetch best setups" });
    }
  });

