  // 📊 FILTER BREAKDOWN: Shows exactly how we get from raw count → filtered count
  // This endpoint explains the data pipeline for transparency
  app.get("/api/performance/filter-breakdown", async (req, res) => {
    try {
      const allIdeas = await storage.getAllTradeIdeas();
      
      // Count at each filter stage
      const totalRaw = allIdeas.length;
      
      // Stage 1: Exclude buggy/test trades
      const afterBuggyFilter = allIdeas.filter(idea => !idea.excludeFromTraining);
      const buggyExcluded = totalRaw - afterBuggyFilter.length;
      
      // Stage 2: Exclude options
      const afterOptionsFilter = afterBuggyFilter.filter(idea => idea.assetType !== 'option');
      const optionsExcluded = afterBuggyFilter.length - afterOptionsFilter.length;
      
      // Stage 3: Exclude flow/lotto sources
      const afterFlowFilter = afterOptionsFilter.filter(idea => idea.source !== 'flow' && idea.source !== 'lotto');
      const flowLottoExcluded = afterOptionsFilter.length - afterFlowFilter.length;
      
      // Stage 4: Exclude legacy engines
      const afterEngineFilter = afterFlowFilter.filter(isCurrentGenEngine);
      const legacyExcluded = afterFlowFilter.length - afterEngineFilter.length;
      
      // Final: Get decided trades (wins + real losses)
      const decidedTrades = getDecidedTrades(afterEngineFilter, { includeAllVersions: true });
      const wins = decidedTrades.filter(idea => idea.outcomeStatus === 'hit_target').length;
      const losses = decidedTrades.length - wins;
      
      // Also count open/expired for context
      const openTrades = afterEngineFilter.filter(idea => idea.outcomeStatus === 'open').length;
      const expiredTrades = afterEngineFilter.filter(idea => idea.outcomeStatus === 'expired').length;
      const breakeven = afterEngineFilter.filter(idea => 
        idea.outcomeStatus === 'hit_stop' && !isRealLoss(idea)
      ).length;
      
      res.json({
        rawTotal: totalRaw,
        filterStages: [
          { stage: 'Raw Database Total', count: totalRaw, excluded: 0, reason: 'All trade ideas in database' },
          { stage: 'After Buggy/Test Filter', count: afterBuggyFilter.length, excluded: buggyExcluded, reason: 'Exclude trades marked as buggy or test data' },
          { stage: 'After Options Filter', count: afterOptionsFilter.length, excluded: optionsExcluded, reason: 'Exclude options (no proper pricing yet)' },
          { stage: 'After Flow/Lotto Filter', count: afterFlowFilter.length, excluded: flowLottoExcluded, reason: 'Exclude flow scanner and lotto trades' },
          { stage: 'After Legacy Engine Filter', count: afterEngineFilter.length, excluded: legacyExcluded, reason: 'Exclude legacy v1.x/v2.x engines' },
        ],
        filteredTotal: afterEngineFilter.length,
        breakdown: {
          open: openTrades,
          expired: expiredTrades,
          breakeven: breakeven,
          decidedWins: wins,
          decidedLosses: losses,
          decidedTotal: decidedTrades.length,
        },
        winRate: decidedTrades.length > 0 
          ? Math.round((wins / decidedTrades.length) * 1000) / 10 
          : 0,
        explanation: `From ${totalRaw} raw trades → ${afterEngineFilter.length} filtered → ${decidedTrades.length} decided (${wins}W/${losses}L)`,
      });
    } catch (error) {
      logger.error("Filter breakdown error:", error);
      res.status(500).json({ error: "Failed to fetch filter breakdown" });
    }
  });

  // ── Grade calibration — the trust test ────────────────────────────────
  // Groups DECIDED trades by the displayed grade family and reports realized
  // win rate + expectancy per grade, via the canonical WinRateService (options
  // judged by real contract P&L). The point: does a higher grade actually
  // produce a better outcome? If the ranking isn't monotonic, the letters are
  // not yet predictive and shouldn't be trusted as trade quality.
  app.get("/api/performance/grade-calibration", async (_req, res) => {
    try {
      const allIdeas = await storage.getAllTradeIdeas();

      // Family = the letter users see. Most decided (historical) ideas carry
      // probabilityBand (A+/A/A-/B+…); fall back to convictionBand (S/A/B/C).
      const familyOf = (i: any): string | null => {
        const pb = String(i.probabilityBand || '').trim().toUpperCase();
        if (/^[ABCDF]/.test(pb)) return pb[0];
        const cb = String(i.convictionBand || '').trim().toUpperCase();
        if (/^[SABC]/.test(cb)) return cb[0];
        return null;
      };

      const FAMILIES = ['S', 'A', 'B', 'C', 'D', 'F'];
      const rows = FAMILIES.map((fam) => {
        const subset = allIdeas.filter((i: any) => familyOf(i) === fam);
        if (subset.length === 0) return null;
        const o = WinRateService.calculate(subset, {}).overall;
        return {
          grade: fam,
          total: subset.length,
          decided: o.decided,
          winRate: o.winRate,
          avgWinPct: o.avgWinPct,
          avgLossPct: o.avgLossPct,
          expectancy: o.expectancy,
          reliable: o.decided >= 20,
        };
      }).filter(Boolean) as any[];

      // Monotonicity check across grades with a reliable decided sample: a lower
      // grade should NOT out-win / out-earn a higher grade (small tolerance).
      const order = ['S', 'A', 'B', 'C', 'D', 'F'];
      const reliable = rows
        .filter((r) => r.reliable)
        .sort((a, b) => order.indexOf(a.grade) - order.indexOf(b.grade));
      let winRateMonotonic = true;
      let expectancyMonotonic = true;
      for (let k = 1; k < reliable.length; k++) {
        if (reliable[k].winRate > reliable[k - 1].winRate + 1) winRateMonotonic = false;
        if (reliable[k].expectancy > reliable[k - 1].expectancy + 0.1) expectancyMonotonic = false;
      }
      const gradesArePredictive = reliable.length >= 2 && winRateMonotonic && expectancyMonotonic;

      res.json({
        rows,
        calibration: {
          reliableGradesCompared: reliable.map((r) => r.grade),
          winRateMonotonic,
          expectancyMonotonic,
          gradesArePredictive,
          verdict:
            reliable.length < 2
              ? 'Not enough decided trades per grade to judge yet — let the engine run and re-check.'
              : gradesArePredictive
                ? 'Higher grades DO produce better realized outcomes — the grades are earning their letters.'
                : 'Higher grades do NOT reliably beat lower ones — grade is not yet predictive. Do not treat a high letter as a better trade.',
        },
        _meta: {
          note: 'Realized win rate + expectancy grouped by displayed grade family via the canonical WinRateService (options judged by real contract P&L). Measures whether grade predicts outcome.',
        },
      });
    } catch (error) {
      logger.error('Grade calibration error:', error);
      res.status(500).json({ error: 'Failed to compute grade calibration' });
    }
  });

  // ── Layer attribution (step 3 of the engine-trust fix) ────────────────
  // Per-layer realized outcome for ideas whose scoring breakdown was persisted
  // (genScoringLayers). A layer whose trades beat baseline is predictive; one at
  // or below baseline is noise — this is the evidence for reweighting the engine.
  // Populates as instrumented ideas resolve (empty until then — expected).
  // ── DISCIPLINE LEDGER — the short gate under the same referee ─────────────
  // Every gate-blocked short is shadow-recorded and replayed here against real
  // daily bars from the block date: which barrier a SHORT would have touched
  // first (target below, stop above; both-touched ties go to the stop, same
  // rule as live validation). "saved" = blocked shorts that would have hit
  // their stop; "cost" = blocked shorts that would have hit their target. The
  // gate keeps its job only while saved outweighs cost.
  app.get("/api/discipline/ledger", async (_req, res) => {
    try {
      const { getLedger } = await import("./discipline-ledger");
      const { resolveBarriers } = await import("@shared/barrier-resolution");
      const { fetchCandles } = await import("./historical-candles");
      const raw = await getLedger();
      const bySymbol = new Map<string, typeof raw>();
      for (const e of raw) {
        if (!bySymbol.has(e.symbol)) bySymbol.set(e.symbol, []);
        bySymbol.get(e.symbol)!.push(e);
      }
      const out: any[] = [];
      for (const [symbol, list] of Array.from(bySymbol.entries())) {
        let bars: { time: number; high: number; low: number; close: number }[] = [];
        try { bars = await fetchCandles(symbol, "3mo", "1d") as any[]; } catch { /* no bars → unreplayable */ }
        for (const e of list) {
          const blockedDay = e.blockedAt.slice(0, 10);
          const since = bars.filter((b) => new Date(b.time * 1000).toISOString().slice(0, 10) >= blockedDay);
          if (since.length === 0) {
            out.push({ ...e, replay: "no bars yet", outcome: "open", wouldBePercent: null });
            continue;
          }
          const highest = Math.max(...since.map((b) => b.high));
          const lowest = Math.min(...since.map((b) => b.low));
          const barrier = resolveBarriers({ direction: "short", target: e.targetPrice, stop: e.stopLoss, highest, lowest });
          const last = since[since.length - 1].close;
          const exit = barrier.outcome === "hit_target" ? e.targetPrice : barrier.outcome === "hit_stop" ? e.stopLoss : last;
          // Short P&L: entry above exit is a gain.
          const wouldBePercent = e.entryPrice > 0 ? ((e.entryPrice - exit) / e.entryPrice) * 100 : null;
          out.push({ ...e, outcome: barrier.outcome, wouldBePercent, lastPrice: last });
        }
      }
      const decided = out.filter((r) => r.outcome === "hit_target" || r.outcome === "hit_stop");
      const cost = decided.filter((r) => r.outcome === "hit_target");   // blocked winner
      const saved = decided.filter((r) => r.outcome === "hit_stop");    // blocked loser
      const sum = (rows: any[]) => rows.reduce((a, r) => a + (Number.isFinite(r.wouldBePercent) ? r.wouldBePercent : 0), 0);
      res.json({
        asOf: new Date().toISOString(),
        totalBlocked: out.length,
        decided: decided.length,
        blockedWinners: cost.length,
        blockedLosers: saved.length,
        netWouldBePercent: Math.round(sum(decided) * 100) / 100,
        entries: out.sort((a, b) => b.blockedAt.localeCompare(a.blockedAt)),
        _meta: {
          note: "Shadow trades — never published, never in the win rate. Replayed on daily bars, so intraday sequencing inside one bar is unknowable; both-barriers-in-one-bar ties go to the stop, matching live validation. netWouldBePercent > 0 means the gate is BLOCKING profitable shorts; sustained positive is the signal to revisit the rule, not to ignore the ledger.",
        },
      });
    } catch (error) {
      res.status(500).json({ error: "Failed to build discipline ledger" });
    }
  });

  // ── BY-SIGNAL COHORTS — does each signal template earn its place? ─────────
  // Every quant idea persists the signal labels that fired (qualitySignals),
  // so new templates (gap_continuation, the volume-unlocked VWAP/spike paths)
  // are trackable as cohorts from the day they shipped. Cohorts start at the
  // clean-era baseline by default — rates across that boundary mix two
  // measurement regimes. An idea with two labels counts in both cohorts; the
  // payload says so rather than pretending the cohorts are disjoint.
  app.get("/api/performance/by-signal", async (req, res) => {
    try {
      const { isRealWin, isRealLoss, reportableRate, OUTCOME_BASELINE_DATE, MIN_REPORTABLE_SAMPLE } = await import('@shared/constants');
      const since = typeof req.query.since === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(req.query.since)
        ? req.query.since : OUTCOME_BASELINE_DATE;
      const all = await storage.getAllTradeIdeas();
      const pool = all.filter((i: any) =>
        !i.excludeFromTraining &&
        typeof i.timestamp === 'string' && i.timestamp.slice(0, 10) >= since &&
        Array.isArray(i.qualitySignals) && i.qualitySignals.length > 0);

      const cohorts = new Map<string, any[]>();
      for (const idea of pool) {
        for (const label of idea.qualitySignals as string[]) {
          // Historical-adjustment annotations are bookkeeping, not templates.
          if (typeof label !== 'string' || label.startsWith('Historical:')) continue;
          if (!cohorts.has(label)) cohorts.set(label, []);
          cohorts.get(label)!.push(idea);
        }
      }

      const signals = [...cohorts.entries()].map(([signal, ideas]) => {
        const open = ideas.filter((i: any) => (i.outcomeStatus ?? 'open') === 'open').length;
        const wins = ideas.filter((i: any) => isRealWin(i));
        const losses = ideas.filter((i: any) => isRealLoss(i));
        const decided = wins.length + losses.length;
        const gains = [...wins, ...losses].map((i: any) => i.percentGain).filter((g: any) => Number.isFinite(g));
        const avgGain = gains.length ? gains.reduce((a: number, b: number) => a + b, 0) / gains.length : null;
        return {
          signal,
          total: ideas.length,
          open,
          wins: wins.length,
          losses: losses.length,
          decided,
          winRate: reportableRate(wins.length, decided),
          avgPercentGain: avgGain,
        };
      }).sort((a, b) => b.total - a.total);

      res.json({
        since,
        baseline: OUTCOME_BASELINE_DATE,
        sampleFloor: MIN_REPORTABLE_SAMPLE,
        ideasInWindow: pool.length,
        signals,
        _meta: {
          note: 'Cohorts overlap: an idea whose scoring fired two templates counts in both. winRate is null under the sample floor — the count is the honest read until then. Rates never span the baseline: before it, the stats layer erased sub-3% stop-outs.',
        },
      });
    } catch (error) {
      res.status(500).json({ error: 'Failed to compute by-signal cohorts' });
    }
  });

  app.get("/api/performance/layer-attribution", async (_req, res) => {
    try {
      const allIdeas = await storage.getAllTradeIdeas();
      const instrumented = allIdeas.filter(
        (i: any) => Array.isArray(i.genScoringLayers) && i.genScoringLayers.length > 0,
      );
      const byLayer = new Map<string, any[]>();
      for (const idea of instrumented) {
        const seen = new Set<string>();
        for (const layer of (idea as any).genScoringLayers) {
          const kind = layer?.kind;
          if (!kind || seen.has(kind)) continue; // count each idea once per layer kind
          seen.add(kind);
          if (!byLayer.has(kind)) byLayer.set(kind, []);
          byLayer.get(kind)!.push(idea);
        }
      }
      const baseline = WinRateService.calculate(instrumented, {}).overall;
      const layers = Array.from(byLayer.entries())
        .map(([kind, ideas]) => {
          const o = WinRateService.calculate(ideas, {}).overall;
          return {
            layer: kind,
            ideas: ideas.length,
            decided: o.decided,
            winRate: o.winRate,
            expectancy: o.expectancy,
            edgeVsBaseline: Math.round((o.expectancy - baseline.expectancy) * 100) / 100,
            predictive: o.decided >= 20 && o.expectancy > baseline.expectancy + 0.1,
          };
        })
        .sort((a, b) => b.edgeVsBaseline - a.edgeVsBaseline);
      res.json({
        instrumentedTotal: instrumented.length,
        ready: instrumented.length >= 50,
        baseline: { decided: baseline.decided, winRate: baseline.winRate, expectancy: baseline.expectancy },
        layers,
        _meta: {
          note: 'Per-layer realized outcome for ideas whose breakdown was persisted (genScoringLayers). Layers above baseline are predictive; at/below are noise. Requires the schema migration + a few weeks of resolved instrumented ideas.',
        },
      });
    } catch (error) {
      logger.error('Layer attribution error:', error);
      res.status(500).json({ error: 'Failed to compute layer attribution' });
    }
  });

  // Performance stats cache (5-minute TTL) - separate cache per filter combination
  const performanceStatsCache = new Map<string, { data: any; timestamp: number }>();
  const PERF_STATS_CACHE_TTL = 5 * 60 * 1000; // 5 minutes
  
  // ── TRACK RECORD BY HORIZON ───────────────────────────────────────────────
  // The headline expectancy hides the actual problem. Day-horizon signals resolve
  // (0-31% expire); swing-horizon signals do not (80-89% expire) regardless of
  // conviction band. That is a horizon-calibration issue, not a signal-quality one,
  // and averaging the two together makes it invisible.
  app.get("/api/performance/by-horizon", async (_req, res) => {
    try {
      const rows: any = await db.execute(sql`
        select
          coalesce(holding_period, 'unspecified') as horizon,
          count(*) n,
          count(*) filter (where outcome_status = 'hit_target') tgt,
          count(*) filter (where outcome_status = 'hit_stop')   stp,
          count(*) filter (where outcome_status = 'expired')    exp,
          round(avg(abs(target_price - entry_price) / nullif(entry_price, 0) * 100)::numeric, 1) avg_target_pct
        from trade_ideas
        where outcome_status in ('hit_target','hit_stop','expired')
          and entry_price > 0
        group by 1
        having count(*) >= 5
        order by count(*) desc
      `);

      const horizons = (rows.rows ?? rows).map((r: any) => {
        const tgt = Number(r.tgt), stp = Number(r.stp), exp = Number(r.exp), n = Number(r.n);
        const decided = tgt + stp;
        return {
          horizon: r.horizon,
          total: n,
          hitTarget: tgt,
          hitStop: stp,
          expired: exp,
          expiredPct: n ? Math.round((exp / n) * 100) : 0,
          // Rate on DECIDED only, with the expired count carried alongside so the
          // number can't be read without seeing how much it excludes.
          decided,
          winRateDecided: decided ? Math.round((tgt / decided) * 1000) / 10 : null,
          avgTargetPct: r.avg_target_pct != null ? Number(r.avg_target_pct) : null,
        };
      });

      res.json({
        horizons,
        _meta: {
          note:
            "winRateDecided counts only trades that tagged a target or a stop. Read it next to expiredPct: a horizon that expires 89% of the time has a win rate computed on a tenth of its signals, which says more about the evaluation window than about the edge.",
        },
      });
    } catch (error) {
      logger.error("Horizon performance error:", error);
      res.status(500).json({ error: "Failed to compute horizon breakdown" });
    }
  });

  app.get("/api/performance/stats", async (req, res) => {
    try {
      const now = Date.now();
      
      // Parse query parameters for filtering
      const startDate = req.query.startDate as string | undefined;
      const endDate = req.query.endDate as string | undefined;
      const source = req.query.source as string | undefined;
      const includeOptions = req.query.includeOptions === 'true';
      
      // Create cache key based on ALL filters (including includeOptions)
      const cacheKey = `${startDate || 'all'}_${endDate || 'all'}_${source || 'all'}_${includeOptions ? 'with-options' : 'no-options'}`;
      
      // Check cache
      const cached = performanceStatsCache.get(cacheKey);
      if (cached && (now - cached.timestamp) < PERF_STATS_CACHE_TTL) {
        logger.info(`[PERF-STATS] Cache hit for filters: ${cacheKey}`);
        return res.json(cached.data);
      }
      
      // Cache miss - fetch fresh data with filters
      logger.info(`[PERF-STATS] Cache miss for filters: ${cacheKey} - fetching fresh data`);
      logger.info(`[PERF-STATS] Filter values: startDate=${startDate}, endDate=${endDate}, source=${source}, includeOptions=${includeOptions}`);
      
      const filters = { startDate, endDate, source, includeOptions };
      const stats = await storage.getPerformanceStats(filters);
      
      // Update cache for this filter combination
      performanceStatsCache.set(cacheKey, { data: stats, timestamp: now });
      logger.info(`[PERF-STATS] Cache updated for filters: ${cacheKey}`);
      
      res.json(stats);
    } catch (error) {
      console.error("Stats error:", error);
      res.status(500).json({ error: "Failed to fetch performance stats" });
    }
  });

  // ============================================================
  // UNIFIED WIN RATE ENDPOINT - Single Source of Truth
  // Uses WinRateService for consistent calculations across platform
  // ============================================================
  /**
   * Both outcome models on the SAME trades, side by side.
   *
   * v1 (canonical, on the marketing page): win = hit_target OR P&L >= +3%;
   * loss = hit_stop AND P&L <= -3%; everything else neutral and EXCLUDED.
   * v2: win = reached T1; loss = hit stop OR ran out of time; unresolved = open only.
   *
   * Deliberately additive. The public 44.5% keeps its definition until these two
   * have been compared on real trades — quietly redefining a number that is
   * printed on the landing page is exactly the failure the page itself warns about.
   */
  /**
   * Current manufactured target vs a structural one, on the SAME live signals.
   *
   * Read-only. Publishes nothing, changes no target. It exists so the swap can be
   * judged on real symbols before it happens — 83% of the book carries a target at
   * an exact round R multiple, so changing the source blind would be the largest
   * unverified change in the system.
   */
  app.get("/api/targets/compare", async (req, res) => {
    try {
      const limit = Math.min(20, Math.max(1, Number(req.query.limit) || 8));
      const { findStructuralTargets } = await import("./structural-targets");

      const base = `http://127.0.0.1:${process.env.PORT || 5000}`;
      const getJson = async (path: string) => {
        try {
          const r = await fetch(base + path);
          return r.ok ? await r.json() : null;
        } catch { return null; }
      };

      const conv: any = await getJson(`/api/convictions?limit=${limit}&minScore=0`);
      const picks: any[] = conv?.picks ?? [];

      const rows = [];
      for (const p of picks) {
        const spot = p.currentPrice ?? p.entryPrice;
        if (!spot) continue;
        const report = await findStructuralTargets(p.symbol, spot, p.direction === 'short' ? 'short' : 'long', {
          fetchGaps: (s) => getJson(`/api/gaps/${s}`),
          fetchGamma: (s) => getJson(`/api/gex/buckets/${s}`),
        });

        const currentT1 = p.targetPrice;
        const risk = p.stopLoss != null ? Math.abs(spot - p.stopLoss) : null;
        const currentRR = risk && currentT1 != null ? Math.abs(currentT1 - spot) / risk : null;
        // Test the ratio the idea was PUBLISHED with, not one recomputed from today's
        // spot. Price moves after publication, so a target that was exactly 2.5R at
        // signal time reads as 2.29R now — recomputing would hide the very signature
        // being looked for. An exact .0/.5 multiple is a target that was computed
        // rather than found.
        const publishedRR = p.riskRewardRatio;
        const manufactured =
          publishedRR != null &&
          Math.abs(publishedRR * 2 - Math.round(publishedRR * 2)) < 0.02;

        const structRR =
          risk && report.primary ? Math.abs(report.primary.price - spot) / risk : null;

        rows.push({
          symbol: p.symbol,
          direction: p.direction,
          spot: +spot.toFixed(2),
          current: {
            t1: currentT1,
            rr: currentRR == null ? null : +currentRR.toFixed(2),
            publishedRR,
            looksManufactured: manufactured,
          },
          structural: report.primary
            ? {
                t1: +report.primary.price.toFixed(2),
                rr: structRR == null ? null : +structRR.toFixed(2),
                source: report.primary.source,
                label: report.primary.label,
                baseRate: report.primary.baseRate,
                baseRateSample: report.primary.baseRateSample,
                medianBarsToReach: report.primary.medianBarsToReach,
              }
            : null,
          note: report.note,
          otherLevels: report.candidates.slice(1, 3).map((c) => `${c.price} (${c.source})`),
        });
      }

      const withStructure = rows.filter((r) => r.structural).length;
      const manufacturedCount = rows.filter((r) => r.current.looksManufactured).length;

      res.json({
        checked: rows.length,
        currentTargetsThatLookManufactured: manufacturedCount,
        signalsWithAStructuralAlternative: withStructure,
        rows,
        note:
          'READ ONLY — proposes, never publishes. baseRate is the symbol\'s own measured gap-fill history; ' +
          'gamma walls return null rather than an invented confidence. Where structural is null there is no ' +
          'destination within 25%, which is a reason to pass on the trade rather than to manufacture a target.',
      });
    } catch (error) {
      logger.error("targets/compare error:", error);
      res.status(500).json({ error: "Failed to compare targets" });
    }
  });

  app.get("/api/performance/win-rate-compare", async (_req, res) => {
    try {
      const { classifyOutcomeV2, realisedR, classifyTrade } = await import("@shared/constants");
      const ideas = await storage.getAllTradeIdeas();

      const v1 = { win: 0, loss: 0, neutral: 0 };
      const v2 = { win: 0, loss: 0, unresolved: 0 };
      const rs: number[] = [];
      const lossReasons: Record<string, number> = {};

      for (const idea of ideas as any[]) {
        v1[classifyTrade(idea)] += 1;

        const o = classifyOutcomeV2(idea);
        v2[o] += 1;
        if (o === 'loss') {
          const st = (idea.outcomeStatus || '(none)').trim().toLowerCase();
          lossReasons[st] = (lossReasons[st] || 0) + 1;
        }
        const r = realisedR(idea);
        if (r !== null) rs.push(r);
      }

      const v1Decided = v1.win + v1.loss;
      const v2Decided = v2.win + v2.loss;
      const expectancyR = rs.length ? rs.reduce((a, b) => a + b, 0) / rs.length : null;

      res.json({
        totalIdeas: ideas.length,
        v1: {
          ...v1,
          decided: v1Decided,
          winRate: v1Decided ? +(100 * v1.win / v1Decided).toFixed(1) : null,
          excluded: v1.neutral,
        },
        v2: {
          ...v2,
          decided: v2Decided,
          winRate: v2Decided ? +(100 * v2.win / v2Decided).toFixed(1) : null,
          lossBreakdown: lossReasons,
        },
        expectancyR: expectancyR === null ? null : +expectancyR.toFixed(3),
        rSampleSize: rs.length,
        // The headline is not the win rate. It is coverage: how much of what this
        // engine publishes ever gets an outcome written back at all.
        coverage: {
          measured: v2.win + v2.loss,
          unresolved: v2.unresolved,
          pctMeasured: ideas.length ? +(100 * (v2.win + v2.loss) / ideas.length).toFixed(1) : 0,
        },
        note:
          'v1 excludes every trade that did not move 3%. v2 counts a measured timeout as a loss ' +
          'but leaves UNMEASURED expiries unresolved — 268 of 367 expired ideas carry percentGain ' +
          '0.00 with a null currentPrice, which is a default that was never written, not a result. ' +
          'Neither win rate means much until coverage is fixed.',
      });
    } catch (error) {
      logger.error("win-rate-compare error:", error);
      res.status(500).json({ error: "Failed to compare win rate models" });
    }
  });

  /**
   * OUTCOME MODEL v2 — the terminal's single performance ledger.
   *
   * This intentionally does not reuse /performance/stats or WinRateService. Those
   * endpoints answer older, filtered questions (including a ±3% stock threshold
   * and option-only subsets). A trader needs one answer to a simpler question:
   * did the published thesis resolve, and did we actually capture the result?
   *
   * The client leads with coverage instead of hiding the unresolved population.
   * A number here is therefore safe to compare over time only when its coverage is
   * shown beside it.
   */
  app.get("/api/performance/outcome-model", async (_req, res) => {
    try {
      const { classifyOutcomeV2, realisedR } = await import("@shared/constants");
      const allIdeas = await storage.getAllTradeIdeas();
      const ideas = allIdeas.filter((idea) => !idea.excludeFromTraining);

      type Counts = { win: number; loss: number; unresolved: number; rValues: number[] };
      const empty = (): Counts => ({ win: 0, loss: 0, unresolved: 0, rValues: [] });
      const totals = empty();
      const bySource = new Map<string, Counts>();
      let measuredTimeouts = 0;
      let unmeasuredTimeouts = 0;

      for (const idea of ideas as any[]) {
        const outcome = classifyOutcomeV2(idea);
        totals[outcome] += 1;
        const r = realisedR(idea);
        if (r !== null) totals.rValues.push(r);

        const source = idea.source || 'unknown';
        const sourceTotals = bySource.get(source) || empty();
        sourceTotals[outcome] += 1;
        if (r !== null) sourceTotals.rValues.push(r);
        bySource.set(source, sourceTotals);

        const status = String(idea.outcomeStatus || '').toLowerCase();
        if (status === 'expired' || status === 'timeout' || status === 'closed_horizon') {
          if (outcome === 'unresolved') unmeasuredTimeouts += 1;
          else measuredTimeouts += 1;
        }
      }

      const decided = totals.win + totals.loss;
      const winRate = decided ? +(totals.win / decided * 100).toFixed(1) : null;
      const averageR = totals.rValues.length
        ? +(totals.rValues.reduce((sum, value) => sum + value, 0) / totals.rValues.length).toFixed(3)
        : null;

      const sources = Array.from(bySource.entries())
        .map(([source, counts]) => {
          const sourceDecided = counts.win + counts.loss;
          return {
            source,
            total: sourceDecided + counts.unresolved,
            win: counts.win,
            loss: counts.loss,
            unresolved: counts.unresolved,
            decided: sourceDecided,
            winRate: sourceDecided ? +(counts.win / sourceDecided * 100).toFixed(1) : null,
            averageR: counts.rValues.length
              ? +(counts.rValues.reduce((sum, value) => sum + value, 0) / counts.rValues.length).toFixed(3)
              : null,
            rSampleSize: counts.rValues.length,
          };
        })
        .sort((a, b) => b.total - a.total);

      // Descriptive attribution only. These slices help diagnose where losses
      // cluster; they do not retune weights automatically and therefore cannot
      // leak the same sample back into the model that produced it.
      const segment = (field: 'direction' | 'holdingPeriod' | 'source') => {
        const groups = new Map<string, Counts>();
        for (const idea of ideas as any[]) {
          const key = String(idea[field] || 'unknown').toLowerCase();
          const counts = groups.get(key) || empty();
          const outcome = classifyOutcomeV2(idea);
          counts[outcome] += 1;
          const r = realisedR(idea);
          if (r !== null) counts.rValues.push(r);
          groups.set(key, counts);
        }
        return Array.from(groups.entries()).map(([name, counts]) => {
          const decided = counts.win + counts.loss;
          const total = decided + counts.unresolved;
          return {
            name, total, decided, win: counts.win, loss: counts.loss, unresolved: counts.unresolved,
            coverage: total ? +(decided / total * 100).toFixed(1) : 0,
            winRate: decided ? +(counts.win / decided * 100).toFixed(1) : null,
            averageR: counts.rValues.length ? +(counts.rValues.reduce((sum, value) => sum + value, 0) / counts.rValues.length).toFixed(3) : null,
            sampleSize: counts.rValues.length,
          };
        }).sort((a, b) => b.decided - a.decided);
      };

      res.json({
        model: 'Outcome model v2',
        totalPublished: ideas.length,
        outcomes: {
          win: totals.win,
          loss: totals.loss,
          unresolved: totals.unresolved,
          decided,
          winRate,
        },
        coverage: {
          measured: decided,
          unresolved: totals.unresolved,
          pctMeasured: ideas.length ? +(decided / ideas.length * 100).toFixed(1) : 0,
        },
        expectancy: {
          averageR,
          sampleSize: totals.rValues.length,
          definition: 'Realised contract/underlying P&L ÷ 50% premium risk. Null when no outcome P&L was written.',
        },
        bySource: sources,
        diagnostics: {
          byDirection: segment('direction'),
          byHorizon: segment('holdingPeriod'),
          bySource: segment('source'),
          warning: 'Descriptive in-sample slices. Use them to form hypotheses, then validate changes on a later out-of-sample period.',
        },
        dataQuality: {
          excludedFromTraining: allIdeas.length - ideas.length,
          measuredTimeouts,
          unmeasuredTimeouts,
        },
        methodology: {
          win: 'Target reached, or a measured closed/expired trade with positive realised P&L.',
          loss: 'Stop reached, or a measured closed/expired trade with negative realised P&L.',
          unresolved: 'Open, or a timeout/close without a real P&L written back. Unresolved trades are not included in win rate or R.',
        },
        asOf: new Date().toISOString(),
      });
    } catch (error) {
      logger.error("outcome-model error:", error);
      res.status(500).json({ error: "Failed to build outcome model" });
    }
  });

  app.get("/api/performance/unified-win-rate", async (req, res) => {
    try {
      const allIdeas = await storage.getAllTradeIdeas();
      
      const filters = {
        startDate: req.query.startDate as string | undefined,
        endDate: req.query.endDate as string | undefined,
        source: req.query.source as string | undefined,
        assetType: req.query.assetType as string | undefined,
        includeOptions: req.query.includeOptions === 'true',
        includeAllVersions: req.query.includeAllVersions === 'true',
      };
      
      const stats = WinRateService.calculate(allIdeas, filters);
      
      res.json({
        success: true,
        ...stats,
        _meta: {
          endpoint: '/api/performance/unified-win-rate',
          description: 'Canonical win rate calculation using WinRateService',
          timestamp: new Date().toISOString(),
        }
      });
    } catch (error) {
      logger.error("Unified win rate error:", error);
      res.status(500).json({ error: "Failed to calculate unified win rate" });
    }
  });

  // ============================================================
  // COMPREHENSIVE TRADE AUDIT ENDPOINT
  // Returns detailed breakdown of all trades with win/loss status
  // ============================================================
  app.get("/api/performance/trade-audit", async (req, res) => {
    try {
      const allIdeas = await storage.getAllTradeIdeas();
      const limit = Math.min(parseInt(req.query.limit as string) || 500, 2000);
      const includeOptions = req.query.includeOptions === 'true';
      const outcomeFilter = req.query.outcome as string; // 'win', 'loss', 'neutral', 'all'

      // Import classifiers from shared constants
      const { isRealWin, isRealLoss, classifyTrade } = await import('@shared/constants');

      // Filter and classify trades
      let auditableIdeas = allIdeas
        .filter(idea => !idea.excludeFromTraining)
        .filter(idea => includeOptions || idea.assetType !== 'option')
        .filter(idea => idea.outcomeStatus !== 'open');

      // Apply outcome filter if specified
      if (outcomeFilter && outcomeFilter !== 'all') {
        auditableIdeas = auditableIdeas.filter(idea => {
          const classification = classifyTrade(idea);
          return classification === outcomeFilter;
        });
      }

      // Sort by timestamp (most recent first)
      auditableIdeas.sort((a, b) =>
        new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()
      );

      // Calculate summary stats
      const allClassified = auditableIdeas.map(idea => ({
        ...idea,
        classification: classifyTrade(idea),
      }));

      const wins = allClassified.filter(i => i.classification === 'win');
      const losses = allClassified.filter(i => i.classification === 'loss');
      const neutral = allClassified.filter(i => i.classification === 'neutral');

      // Calculate P&L stats
      const totalWinPnL = wins.reduce((sum, i) => sum + (i.percentGain || 0), 0);
      const totalLossPnL = losses.reduce((sum, i) => sum + (i.percentGain || 0), 0);
      const avgWinPnL = wins.length > 0 ? totalWinPnL / wins.length : 0;
      const avgLossPnL = losses.length > 0 ? Math.abs(totalLossPnL / losses.length) : 0;

      // Decided trades (wins + losses)
      const decided = wins.length + losses.length;
      const winRate = decided > 0 ? (wins.length / decided) * 100 : 0;

      // Expectancy calculation
      const winProb = decided > 0 ? wins.length / decided : 0;
      const lossProb = decided > 0 ? losses.length / decided : 0;
      const expectancy = (winProb * avgWinPnL) - (lossProb * avgLossPnL);

      // Return limited trades with audit details
      const auditedTrades = allClassified.slice(0, limit).map(idea => ({
        id: idea.id,
        symbol: idea.symbol,
        assetType: idea.assetType,
        direction: idea.direction,
        optionType: idea.optionType || null,
        strikePrice: idea.strikePrice || null,
        expiryDate: idea.expiryDate || null,
        source: idea.source,
        entryPrice: idea.entryPrice,
        targetPrice: idea.targetPrice,
        stopLoss: idea.stopLoss,
        outcomeStatus: idea.outcomeStatus,
        percentGain: idea.percentGain,
        realizedPnL: idea.realizedPnL || null,
        timestamp: idea.timestamp,
        exitDate: idea.exitDate || null,
        classification: idea.classification,
        confidenceScore: idea.confidenceScore,
        probabilityBand: idea.probabilityBand,
        holdingPeriod: idea.holdingPeriod,
      }));

      res.json({
        success: true,
        summary: {
          totalTrades: allClassified.length,
          wins: wins.length,
          losses: losses.length,
          neutral: neutral.length,
          decided,
          winRate: Math.round(winRate * 10) / 10,
          avgWinPercent: Math.round(avgWinPnL * 10) / 10,
          avgLossPercent: Math.round(avgLossPnL * 10) / 10,
          expectancy: Math.round(expectancy * 100) / 100,
          profitFactor: avgLossPnL > 0 ? Math.round((avgWinPnL / avgLossPnL) * 100) / 100 : 0,
        },
        byAssetType: {
          stock: {
            wins: wins.filter(i => i.assetType === 'stock').length,
            losses: losses.filter(i => i.assetType === 'stock').length,
          },
          option: {
            wins: wins.filter(i => i.assetType === 'option').length,
            losses: losses.filter(i => i.assetType === 'option').length,
          },
          crypto: {
            wins: wins.filter(i => i.assetType === 'crypto').length,
            losses: losses.filter(i => i.assetType === 'crypto').length,
          },
        },
        bySource: Object.fromEntries(
          Array.from(new Set(allClassified.map(i => i.source || 'unknown')))
            .map(source => [
              source,
              {
                wins: wins.filter(i => i.source === source).length,
                losses: losses.filter(i => i.source === source).length,
                total: allClassified.filter(i => i.source === source).length,
              }
            ])
        ),
        topWinners: wins.slice(0, 10).map(i => ({
          symbol: i.symbol,
          percentGain: i.percentGain,
          source: i.source,
          timestamp: i.timestamp,
        })),
        topLosers: losses.sort((a, b) => (a.percentGain || 0) - (b.percentGain || 0)).slice(0, 10).map(i => ({
          symbol: i.symbol,
          percentGain: i.percentGain,
          source: i.source,
          timestamp: i.timestamp,
        })),
        trades: auditedTrades,
        _meta: {
          endpoint: '/api/performance/trade-audit',
          description: 'Comprehensive trade audit with win/loss breakdown',
          timestamp: new Date().toISOString(),
          filters: {
            includeOptions,
            outcomeFilter: outcomeFilter || 'all',
            limit,
          },
        },
      });
    } catch (error) {
      logger.error("Trade audit error:", error);
      res.status(500).json({ error: "Failed to generate trade audit" });
    }
  });

  // GEX Big Gainers — top plays from the GEX scanner that ran (or are running) hot.
  // A leaderboard, not a hard cutoff: GEX plays are tracked as underlying-stock entries,
  // so moves are single-/low-double-digit %. Both buckets rank by gain desc and cap at `limit`,
  // with an optional `threshold` floor (default 0 = any positive gainer). No auth gate.
  // Two buckets: `live` = still-open plays by peak run-up, `closed` = resolved winners by realized %.
  app.get("/api/gex/big-gainers", async (req, res) => {
    try {
      const parsed = parseFloat(req.query.threshold as string);
      const threshold = Number.isFinite(parsed) ? Math.max(0, parsed) : 0;
      const limit = Math.min(parseInt(req.query.limit as string) || 20, 100);

      const allIdeas = await storage.getAllTradeIdeas();
      // String() cast: 'gex_scanner' is written via `as any` and isn't in the IdeaSource union.
      const gexIdeas = allIdeas.filter(i => String(i.source) === 'gex_scanner');

      // Direction-aware peak run-up from the high/low watermarks the validation service maintains.
      const peakRunup = (idea: typeof gexIdeas[number]): number => {
        const entry = idea.entryPrice;
        if (!entry || entry <= 0) return 0;
        if (idea.direction === 'short') {
          const low = idea.lowestPriceReached;
          if (low == null) return 0;
          return ((entry - low) / entry) * 100;
        }
        const high = idea.highestPriceReached;
        if (high == null) return 0;
        return ((high - entry) / entry) * 100;
      };

      const peakPriceOf = (idea: typeof gexIdeas[number]): number | null =>
        idea.direction === 'short' ? idea.lowestPriceReached ?? null : idea.highestPriceReached ?? null;

      // Gamma regime parsed from qualitySignals (e.g. "gamma_regime:positive_gamma"); null if absent.
      const regimeOf = (idea: typeof gexIdeas[number]): string | null => {
        const sig = (idea.qualitySignals || []).find(s => s.startsWith('gamma_regime:'));
        return sig ? sig.slice('gamma_regime:'.length) : null;
      };

      // Direction-consistent, regime-aware one-liner. The raw catalyst can read bullish on a SHORT
      // (it omits the bias rationale), so the board shows THIS instead — a SHORT never reads as a buy.
      const rationaleOf = (idea: typeof gexIdeas[number]): string => {
        const short = idea.direction === 'short';
        switch (regimeOf(idea)) {
          case 'positive_gamma':
            return short ? 'Fade extension — pin down to gamma magnet' : 'Pin up to gamma magnet';
          case 'negative_gamma':
            return short ? 'Momentum down to put wall' : 'Momentum up to call wall';
          case 'transitioning':
            return short ? 'Lean short into gamma flip' : 'Lean long into gamma flip';
          default:
            return short ? 'Short setup — target below entry' : 'Long setup — target above entry';
        }
      };

      const live = gexIdeas
        .filter(i => i.outcomeStatus === 'open')
        .map(i => ({ idea: i, peakGain: peakRunup(i) }))
        .filter(x => x.peakGain > 0 && x.peakGain >= threshold)
        .sort((a, b) => b.peakGain - a.peakGain)
        .slice(0, limit)
        .map(({ idea, peakGain }) => ({
          id: idea.id,
          symbol: idea.symbol,
          assetType: idea.assetType,
          direction: idea.direction,
          optionType: idea.optionType || null,
          strikePrice: idea.strikePrice || null,
          expiryDate: idea.expiryDate || null,
          entryPrice: idea.entryPrice,
          targetPrice: idea.targetPrice,
          peakPrice: peakPriceOf(idea),
          peakGain: Math.round(peakGain * 10) / 10,
          regime: regimeOf(idea),
          rationale: rationaleOf(idea),
          catalyst: idea.catalyst || null,
          timestamp: idea.timestamp,
        }));

      const closed = gexIdeas
        .filter(i => i.outcomeStatus !== 'open' && (i.percentGain || 0) > 0 && (i.percentGain || 0) >= threshold)
        .sort((a, b) => (b.percentGain || 0) - (a.percentGain || 0))
        .slice(0, limit)
        .map(idea => ({
          id: idea.id,
          symbol: idea.symbol,
          assetType: idea.assetType,
          direction: idea.direction,
          optionType: idea.optionType || null,
          strikePrice: idea.strikePrice || null,
          expiryDate: idea.expiryDate || null,
          entryPrice: idea.entryPrice,
          exitPrice: idea.exitPrice ?? null,
          percentGain: idea.percentGain != null ? Math.round(idea.percentGain * 10) / 10 : null,
          outcomeStatus: idea.outcomeStatus,
          regime: regimeOf(idea),
          rationale: rationaleOf(idea),
          catalyst: idea.catalyst || null,
          timestamp: idea.timestamp,
          exitDate: idea.exitDate || null,
        }));

      res.json({
        success: true,
        threshold,
        live,
        closed,
        _meta: {
          endpoint: '/api/gex/big-gainers',
          description: 'Premium GEX-scanner plays running hot (live) or resolved as winners (closed)',
          totalGexIdeas: gexIdeas.length,
          timestamp: new Date().toISOString(),
        },
      });
    } catch (error) {
      logger.error("GEX big-gainers error:", error);
      res.status(500).json({ error: "Failed to load GEX big gainers" });
    }
  });

  // Engine Performance Breakdown cache (5-minute TTL)
  let engineBreakdownCache: { data: any; timestamp: number } | null = null;
  const ENGINE_BREAKDOWN_CACHE_TTL = 5 * 60 * 1000; // 5 minutes
  
  // Engine Performance Breakdown - Compare AI vs Quant vs Hybrid vs Flow
  app.get("/api/performance/engine-breakdown", async (_req, res) => {
    try {
      const now = Date.now();
      
      // Check cache
      if (engineBreakdownCache && (now - engineBreakdownCache.timestamp) < ENGINE_BREAKDOWN_CACHE_TTL) {
        return res.json(engineBreakdownCache.data);
      }
      
      const filters = { includeOptions: false }; // stock engines: stock-level outcomes only

      // Stock engines (ai/quant/hybrid) — stock-level win/loss, unchanged.
      const [aiStats, quantStats, hybridStats] = await Promise.all([
        storage.getPerformanceStats({ ...filters, source: 'ai' }),
        storage.getPerformanceStats({ ...filters, source: 'quant' }),
        storage.getPerformanceStats({ ...filters, source: 'hybrid' }),
      ]);

      // FLOW/options: measured by REAL option contract P&L (entry vs exit
      // premium) via the canonical WinRateService — which counts ONLY option
      // ideas that carry a captured optionPercentGain. This replaces the old
      // stock-vs-premium winRate (storage.getPerformanceStats) that compared
      // the underlying stock price to the option premium and produced false
      // wins (the bogus ~99.7%). Unmeasured option ideas are excluded, never
      // scored as wins.
      // One canonical pass over all ideas; the option asset-type row IS the
      // honest Flow/options scorecard (winRate, decided count and expectancy all
      // drawn from the SAME measured-contract population — no mixing).
      const allIdeasForFlow = await storage.getAllTradeIdeas();
      const optStats = WinRateService.calculate(allIdeasForFlow, {})
        .byAssetType.find((c: any) => c.category === 'option')?.stats;

      // Grade sample size: A (50+), B (20-49), C (10-19), D (5-9), F (<5)
      const gradeFor = (n: number) =>
        n >= 50 ? "A" : n >= 20 ? "B" : n >= 10 ? "C" : n >= 5 ? "D" : "F";

      const mapEngine = (stats: any) => {
        const s = stats.overall;
        const sampleSize = s.closedIdeas || 0;
        return {
          totalIdeas: s.totalIdeas,
          closedIdeas: s.closedIdeas,
          winRate: s.winRate,
          avgPercentGain: s.avgPercentGain,
          sampleSize,
          sampleGrade: gradeFor(sampleSize),
          reliable: sampleSize >= 10,
        };
      };

      const flowDecided = optStats?.decided ?? 0;
      const flow = {
        totalIdeas: optStats?.total ?? 0,
        closedIdeas: flowDecided,
        winRate: optStats?.winRate ?? 0,
        // Expectancy = average per-trade contract P&L over decided trades.
        avgPercentGain: optStats?.expectancy ?? 0,
        avgWinPct: optStats?.avgWinPct ?? 0,
        avgLossPct: optStats?.avgLossPct ?? 0,
        sampleSize: flowDecided,
        sampleGrade: gradeFor(flowDecided),
        reliable: flowDecided >= 10,
        measuredBy: "option_contract_pnl",
        _note: "Measured by real option contract P&L (entry vs exit premium). Option ideas without a captured contract P&L are excluded — never counted as wins.",
      };

      const data = {
        ai: mapEngine(aiStats),
        quant: mapEngine(quantStats),
        hybrid: mapEngine(hybridStats),
        flow,
        _meta: {
          note: "Hit rates are count-based (wins / decided). Stock engines (AI, Quant, Hybrid) use stock-level target/stop outcomes; Flow/Lotto use real option contract P&L via WinRateService.",
          optionsMeasuredBy: "contract_pnl",
        },
      };
      
      // Update cache
      engineBreakdownCache = { data, timestamp: now };
      
      res.json(data);
    } catch (error) {
      console.error("Engine breakdown error:", error);
      res.status(500).json({ error: "Failed to fetch engine breakdown" });
    }
  });

  app.get("/api/performance/export", async (_req, res) => {
    try {
      const allIdeas = await storage.getAllTradeIdeas();
      const closedIdeas = allIdeas.filter((idea) => idea.outcomeStatus !== 'open');
      
      // Build CSV
      const headers = [
        'ID', 'Symbol', 'Asset Type', 'Direction', 'Source', 
        'Entry Price', 'Target Price', 'Stop Loss', 'Exit Price',
        'R:R Ratio', 'Percent Gain', 'Outcome Status', 'Resolution Reason',
        'Created At', 'Exit Date', 'Holding Time (min)',
        'Confidence Score', 'Probability Band', 'Quality Signals',
        'Catalyst'
      ].join(',');

      const rows = closedIdeas.map((idea) => {
        return [
          idea.id,
          idea.symbol,
          idea.assetType,
          idea.direction,
          idea.source || 'unknown',
          idea.entryPrice,
          idea.targetPrice,
          idea.stopLoss,
          idea.exitPrice || '',
          idea.riskRewardRatio,
          idea.percentGain || '',
          idea.outcomeStatus,
          idea.resolutionReason || '',
          idea.timestamp,
          idea.exitDate || '',
          idea.actualHoldingTimeMinutes || '',
          idea.confidenceScore,
          idea.probabilityBand,
          (idea.qualitySignals || []).join(';'),
          `"${idea.catalyst.replace(/"/g, '""')}"`, // Escape quotes in catalyst
        ].join(',');
      });

      const csv = [headers, ...rows].join('\n');
      
      res.setHeader('Content-Type', 'text/csv');
      res.setHeader('Content-Disposition', 'attachment; filename="trade-ideas-performance.csv"');
      res.send(csv);
    } catch (error) {
      console.error("Export error:", error);
      res.status(500).json({ error: "Failed to export data" });
    }
  });

  // Advanced Performance Analytics Endpoints (Advanced tier required)

  // 1. Symbol Leaderboard - Top/Bottom performing symbols
  app.get("/api/performance/symbol-leaderboard", requireTier('canAccessSymbolLeaderboard'), async (req, res) => {
    try {
      const engine = req.query.engine as string | undefined;
      
      // Get all trade ideas
      const allIdeas = await storage.getAllTradeIdeas();
      
      // 🔧 DATA INTEGRITY: Use canonical filters from storage.ts
      // Filter: DECIDED trades only (auto-resolved wins + real losses)
      let filteredIdeas = getDecidedTradesByResolution(allIdeas, { includeAllVersions: false });
      
      if (engine) {
        filteredIdeas = filteredIdeas.filter(idea => idea.source === engine);
      }
      
      // Group by symbol
      const symbolStats = new Map<string, {
        symbol: string;
        trades: typeof filteredIdeas;
        wins: number;
        losses: number;
      }>();
      
      filteredIdeas.forEach(idea => {
        if (!symbolStats.has(idea.symbol)) {
          symbolStats.set(idea.symbol, {
            symbol: idea.symbol,
            trades: [],
            wins: 0,
            losses: 0,
          });
        }
        
        const stats = symbolStats.get(idea.symbol)!;
        stats.trades.push(idea);
        
        if (idea.resolutionReason === 'auto_target_hit') {
          stats.wins++;
        } else if (isRealLossByResolution(idea)) {
          stats.losses++;
        }
      });
      
      // 🔧 SAMPLE SIZE GATING: Min 20 trades required for statistical reliability
      // Symbols with <50 trades get a warning badge
      const MIN_TRADES_FOR_DISPLAY = 20;
      const MIN_TRADES_FOR_CONFIDENCE = 50;
      
      const leaderboard: SymbolLeaderboardEntry[] = [];
      
      symbolStats.forEach(stats => {
        // Hide symbols with <20 trades - statistically meaningless
        if (stats.trades.length < MIN_TRADES_FOR_DISPLAY) return;
        
        const totalTrades = stats.trades.length;
        const winRate = totalTrades > 0 ? (stats.wins / totalTrades) * 100 : 0;
        
        // Calculate avg gain on wins
        const winningTrades = stats.trades.filter(t => t.resolutionReason === 'auto_target_hit');
        const avgGainOnWins = winningTrades.length > 0
          ? winningTrades.reduce((sum, t) => sum + (t.percentGain || 0), 0) / winningTrades.length
          : 0;
        
        // Calculate avg loss on losses
        const losingTrades = stats.trades.filter(t => t.resolutionReason === 'auto_stop_hit');
        const avgLossOnLosses = losingTrades.length > 0
          ? losingTrades.reduce((sum, t) => sum + (t.percentGain || 0), 0) / losingTrades.length
          : 0;
        
        leaderboard.push({
          symbol: stats.symbol,
          trades: totalTrades,
          wins: stats.wins,
          losses: stats.losses,
          winRate: Math.round(winRate * 10) / 10,
          avgGain: Math.round(avgGainOnWins * 10) / 10,
          avgLoss: Math.round(avgLossOnLosses * 10) / 10,
          sampleWarning: totalTrades < MIN_TRADES_FOR_CONFIDENCE, // Warn if <50 trades
        });
      });
      
      // Sort by winRate DESC, then by trades DESC
      leaderboard.sort((a, b) => {
        if (b.winRate !== a.winRate) {
          return b.winRate - a.winRate;
        }
        return b.trades - a.trades;
      });
      
      // Get top 20 winners and bottom 10 losers
      const topPerformers = leaderboard.slice(0, 20);
      const underperformers = leaderboard.slice(-10).reverse();
      
      res.json({
        topPerformers,
        underperformers,
      });
    } catch (error) {
      logger.error("Symbol leaderboard error:", error);
      res.status(500).json({ error: "Failed to fetch symbol leaderboard" });
    }
  });

  // 2. Time of Day Heatmap - Win rate by hour (9 AM - 4 PM ET)
  app.get("/api/performance/time-of-day-heatmap", requireTier('canAccessTimeHeatmap'), async (req, res) => {
    try {
      const engine = req.query.engine as string | undefined;
      
      // Get all trade ideas
      const allIdeas = await storage.getAllTradeIdeas();
      
      // Filter: only auto-resolved trades + optional engine filter
      // Also filter out trades with synthetic exit timestamps (exactly 12:00:00)
      let filteredIdeas = allIdeas.filter(idea => {
        // Must be auto-resolved
        if (idea.resolutionReason !== 'auto_target_hit' && idea.resolutionReason !== 'auto_stop_hit') {
          return false;
        }
        
        // Must have a valid exitDate (not null)
        if (!idea.exitDate) {
          return false;
        }
        
        // Filter out synthetic 12:00:00 timestamps
        // These are likely placeholder values, not real exit times
        try {
          const exitDate = new Date(idea.exitDate);
          const exitHour = exitDate.getUTCHours();
          const exitMinute = exitDate.getUTCMinutes();
          const exitSecond = exitDate.getUTCSeconds();
          
          // Also check in ET timezone
          const etTimeStr = formatInTimeZone(exitDate, 'America/New_York', 'HH:mm:ss');
          const isSyntheticET = etTimeStr === '12:00:00';
          
          // Filter out if exactly 12:00:00 UTC or 12:00:00 ET (likely synthetic)
          if ((exitHour === 12 && exitMinute === 0 && exitSecond === 0) || isSyntheticET) {
            return false;
          }
        } catch {
          // If we can't parse the exit date, exclude it
          return false;
        }
        
        return true;
      });
      
      if (engine) {
        filteredIdeas = filteredIdeas.filter(idea => idea.source === engine);
      }
      
      // Group by hour (ET timezone)
      const hourlyStats = new Map<number, {
        hour: number;
        trades: typeof filteredIdeas;
        wins: number;
        losses: number;
      }>();
      
      // Initialize hours 9-16 (9 AM - 4 PM ET)
      for (let hour = 9; hour <= 16; hour++) {
        hourlyStats.set(hour, {
          hour,
          trades: [],
          wins: 0,
          losses: 0,
        });
      }
      
      filteredIdeas.forEach(idea => {
        try {
          // Convert timestamp to ET timezone and extract hour
          const etHour = parseInt(formatInTimeZone(new Date(idea.timestamp), 'America/New_York', 'H'));
          
          // Only include market hours (9 AM - 4 PM)
          if (etHour >= 9 && etHour <= 16) {
            const stats = hourlyStats.get(etHour)!;
            stats.trades.push(idea);
            
            if (idea.resolutionReason === 'auto_target_hit') {
              stats.wins++;
            } else if (idea.resolutionReason === 'auto_stop_hit') {
              stats.losses++;
            }
          }
        } catch (error) {
          logger.error(`Failed to parse timestamp for idea ${idea.id}:`, error);
        }
      });
      
      // Calculate win rates
      const heatmap: TimeOfDayHeatmapEntry[] = [];
      
      hourlyStats.forEach(stats => {
        const totalTrades = stats.trades.length;
        const winRate = totalTrades > 0 ? (stats.wins / totalTrades) * 100 : 0;
        
        // Format hour label (e.g., "9 AM", "12 PM", "4 PM")
        const hourLabel = stats.hour === 12 
          ? "12 PM" 
          : stats.hour > 12 
            ? `${stats.hour - 12} PM` 
            : `${stats.hour} AM`;
        
        heatmap.push({
          hour: stats.hour,
          hourLabel,
          trades: totalTrades,
          wins: stats.wins,
          losses: stats.losses,
          winRate: Math.round(winRate * 10) / 10,
        });
      });
      
      // Sort by hour
      heatmap.sort((a, b) => a.hour - b.hour);
      
      res.json(heatmap);
    } catch (error) {
      logger.error("Time-of-day heatmap error:", error);
      res.status(500).json({ error: "Failed to fetch time-of-day heatmap" });
    }
  });

  // 3. Engine Trends - Weekly performance for each engine over last 8 weeks
  app.get("/api/performance/engine-trends", requireTier('canAccessEngineTrends'), async (req, res) => {
    try {
      // Get all trade ideas
      const allIdeas = await storage.getAllTradeIdeas();
      
      // 🔧 DATA INTEGRITY: Use canonical filters from storage.ts
      // Filter: DECIDED trades only (auto-resolved wins + real losses)
      const filteredIdeas = getDecidedTradesByResolution(allIdeas, { includeAllVersions: false });
      
      // Get date 8 weeks ago
      const eightWeeksAgo = new Date();
      eightWeeksAgo.setDate(eightWeeksAgo.getDate() - (8 * 7));
      
      // Filter to last 8 weeks only
      const recentIdeas = filteredIdeas.filter(idea => {
        const ideaDate = new Date(idea.timestamp);
        return ideaDate >= eightWeeksAgo;
      });
      
      // Group by engine and week
      const engineWeekStats = new Map<string, {
        engine: string;
        week: string;
        trades: typeof recentIdeas;
        wins: number;
      }>();
      
      recentIdeas.forEach(idea => {
        const engine = idea.source || 'unknown';
        
        // Get start of week (Monday) in ET timezone
        const ideaDate = new Date(idea.timestamp);
        const dayOfWeek = ideaDate.getDay();
        const diff = ideaDate.getDate() - dayOfWeek + (dayOfWeek === 0 ? -6 : 1); // Adjust when day is Sunday
        const weekStart = new Date(ideaDate.setDate(diff));
        weekStart.setHours(0, 0, 0, 0);
        const weekKey = weekStart.toISOString().split('T')[0]; // YYYY-MM-DD format
        
        const key = `${engine}_${weekKey}`;
        
        if (!engineWeekStats.has(key)) {
          engineWeekStats.set(key, {
            engine,
            week: weekKey,
            trades: [],
            wins: 0,
          });
        }
        
        const stats = engineWeekStats.get(key)!;
        stats.trades.push(idea);
        
        if (idea.resolutionReason === 'auto_target_hit') {
          stats.wins++;
        }
      });
      
      // Pivot data: group by week, with each engine as a column
      const weeklyData = new Map<string, {
        week: string;
        weekLabel: string;
        ai: number;
        quant: number;
        hybrid: number;
        flow: number;
        news: number;
      }>();
      
      // Get all unique weeks
      const uniqueWeeks = new Set<string>();
      engineWeekStats.forEach((_, key) => {
        const week = key.split('_')[1];
        uniqueWeeks.add(week);
      });
      
      // Initialize each week with 0 win rates
      uniqueWeeks.forEach(week => {
        const weekDate = new Date(week);
        const monthNames = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
        const weekLabel = `${monthNames[weekDate.getMonth()]} ${weekDate.getDate()}`;
        
        weeklyData.set(week, {
          week,
          weekLabel,
          ai: 0,
          quant: 0,
          hybrid: 0,
          flow: 0,
          news: 0,
        });
      });
      
      // Calculate win rates for each engine per week
      engineWeekStats.forEach(stats => {
        const totalTrades = stats.trades.length;
        const winRate = totalTrades > 0 ? Math.round((stats.wins / totalTrades) * 1000) / 10 : 0;
        
        const weekData = weeklyData.get(stats.week);
        if (weekData) {
          const engine = stats.engine.toLowerCase();
          if (engine === 'ai') weekData.ai = winRate;
          else if (engine === 'quant') weekData.quant = winRate;
          else if (engine === 'hybrid') weekData.hybrid = winRate;
          else if (engine === 'flow') weekData.flow = winRate;
          else if (engine === 'news') weekData.news = winRate;
        }
      });
      
      // Convert to array and sort by week ASC (oldest first for chart display)
      const trends = Array.from(weeklyData.values()).sort((a, b) => a.week.localeCompare(b.week));
      
      res.json(trends);
    } catch (error) {
      logger.error("Engine trends error:", error);
      res.status(500).json({ error: "Failed to fetch engine trends" });
    }
  });

  // 4. Signal Strength Analysis - Win rate by actual signal consensus (# of agreeing indicators)
  // NEW: Groups by qualitySignals array length, NOT legacy confidence percentages
  app.get("/api/performance/confidence-calibration", async (req, res) => {
    try {
      const engine = req.query.engine as string | undefined;
      
      // Get all trade ideas
      const allIdeas = await storage.getAllTradeIdeas();
      
      // 🔧 DATA INTEGRITY: Use shared canonical filters for consistency (include Flow)
      const preFiltered = applyCanonicalPerformanceFilters(allIdeas, { includeFlowLotto: true });
      
      // Get decided trades only (auto-resolved wins + real losses)
      let filteredIdeas = getDecidedTradesByResolution(preFiltered, { includeAllVersions: false });
      
      if (engine) {
        filteredIdeas = filteredIdeas.filter(idea => idea.source === engine);
      }
      
      // NEW: Group by ACTUAL signal count (qualitySignals array length)
      // Signal Strength Bands: A (5+), B+ (4), B (3), C+ (2), C (1), D (0)
      const signalBands = ['A', 'B+', 'B', 'C+', 'C', 'D'];
      const bandStats = new Map<string, {
        band: string;
        signalCount: string;
        trades: typeof filteredIdeas;
        wins: number;
      }>();
      
      signalBands.forEach(band => {
        const signalCount = band === 'A' ? '5+' : band === 'B+' ? '4' : band === 'B' ? '3' : band === 'C+' ? '2' : band === 'C' ? '1' : '0';
        bandStats.set(band, {
          band,
          signalCount,
          trades: [],
          wins: 0,
        });
      });
      
      filteredIdeas.forEach(idea => {
        // Count actual signals from qualitySignals array
        const signalCount = idea.qualitySignals?.length || 0;
        
        // Map signal count to band
        let band: string;
        if (signalCount >= 5) band = 'A';
        else if (signalCount === 4) band = 'B+';
        else if (signalCount === 3) band = 'B';
        else if (signalCount === 2) band = 'C+';
        else if (signalCount === 1) band = 'C';
        else band = 'D';
        
        const stats = bandStats.get(band)!;
        stats.trades.push(idea);
        
        if (idea.resolutionReason === 'auto_target_hit') {
          stats.wins++;
        }
      });
      
      // Calculate win rates
      const calibration: SignalStrengthEntry[] = [];
      
      // Band label mapping for display - shows signal count, not fake probability
      const bandLabels: Record<string, string> = {
        'A': 'A (5+ signals)',
        'B+': 'B+ (4 signals)',
        'B': 'B (3 signals)',
        'C+': 'C+ (2 signals)',
        'C': 'C (1 signal)',
        'D': 'D (0 signals)'
      };
      
      // Return in order from strongest to weakest signal consensus
      signalBands.forEach(band => {
        const stats = bandStats.get(band)!;
        const totalTrades = stats.trades.length;
        const losses = totalTrades - stats.wins;
        const winRate = totalTrades > 0 ? (stats.wins / totalTrades) * 100 : 0;
        
        calibration.push({
          band: stats.band,
          bandLabel: bandLabels[stats.band] || stats.band,
          trades: totalTrades,
          wins: stats.wins,
          losses: losses,
          winRate: Math.round(winRate * 10) / 10,
        });
      });
      
      res.json(calibration);
    } catch (error) {
      logger.error("Signal strength analysis error:", error);
      res.status(500).json({ error: "Failed to fetch signal strength analysis" });
    }
  });

  // Signal Strength Stats - Uses ACTUAL signal counts from qualitySignals array
  // HONEST DATA: No more fake probability percentages
  // NOTE: Uses same filters as /api/performance/stats for consistency
  app.get("/api/performance/calibrated-stats", async (req, res) => {
    try {
      const allIdeas = await storage.getAllTradeIdeas();
      
      // Use SAME filters as main performance stats to avoid data mismatch
      // Default filters: excludes options/lotto for consistency with headline win rate
      const filteredIdeas = applyCanonicalPerformanceFilters(allIdeas);
      
      // Get decided trades only (wins + real losses, excludes breakeven, expired, and legacy engines)
      const resolvedIdeas = getDecidedTrades(filteredIdeas, { includeAllVersions: false });
      
      // NEW: Group by ACTUAL signal count (qualitySignals.length), not fake confidence scores
      // Signal Strength Bands: A (5+), B+ (4), B (3), C+ (2), C (1), D (0)
      const bands = [
        { name: 'A (5+ signals)', key: 'A', minSignals: 5, maxSignals: 999, wins: 0, losses: 0 },
        { name: 'B+ (4 signals)', key: 'B+', minSignals: 4, maxSignals: 4, wins: 0, losses: 0 },
        { name: 'B (3 signals)', key: 'B', minSignals: 3, maxSignals: 3, wins: 0, losses: 0 },
        { name: 'C+ (2 signals)', key: 'C+', minSignals: 2, maxSignals: 2, wins: 0, losses: 0 },
        { name: 'C (1 signal)', key: 'C', minSignals: 1, maxSignals: 1, wins: 0, losses: 0 },
        { name: 'D (0 signals)', key: 'D', minSignals: 0, maxSignals: 0, wins: 0, losses: 0 },
      ];
      
      resolvedIdeas.forEach(idea => {
        // Use ACTUAL signal count from qualitySignals array
        const signalCount = idea.qualitySignals?.length || 0;
        const isWin = idea.outcomeStatus === 'hit_target';
        
        const band = bands.find(b => signalCount >= b.minSignals && signalCount <= b.maxSignals);
        if (band) {
          if (isWin) band.wins++;
          else band.losses++;
        }
      });
      
      // Calculate win rates for each band - CONSOLIDATED to A, B, C, D for external display
      // Internally we keep A/B+/B/C+/C/D, but externally we show only A/B/C/D
      const coarseBands = [
        { letter: 'A', wins: 0, losses: 0, detailedBands: ['A (5+ signals)'] },
        { letter: 'B', wins: 0, losses: 0, detailedBands: [] as string[] },
        { letter: 'C', wins: 0, losses: 0, detailedBands: [] as string[] },
        { letter: 'D', wins: 0, losses: 0, detailedBands: ['D (0 signals)'] },
      ];
      
      // Map detailed bands to coarse bands
      for (const band of bands) {
        if (band.key === 'A') {
          coarseBands[0].wins += band.wins;
          coarseBands[0].losses += band.losses;
        } else if (band.key === 'B+' || band.key === 'B') {
          coarseBands[1].wins += band.wins;
          coarseBands[1].losses += band.losses;
          if (!coarseBands[1].detailedBands.includes(band.name)) {
            coarseBands[1].detailedBands.push(band.name);
          }
        } else if (band.key === 'C+' || band.key === 'C') {
          coarseBands[2].wins += band.wins;
          coarseBands[2].losses += band.losses;
          if (!coarseBands[2].detailedBands.includes(band.name)) {
            coarseBands[2].detailedBands.push(band.name);
          }
        } else if (band.key === 'D') {
          coarseBands[3].wins += band.wins;
          coarseBands[3].losses += band.losses;
        }
      }
      
      // Return consolidated breakdown with coarse bands (A, B, C, D only)
      const confidenceBreakdown = coarseBands.map(band => ({
        level: band.letter,
        trades: band.wins + band.losses,
        wins: band.wins,
        losses: band.losses,
        winRate: band.wins + band.losses > 0 
          ? Math.round((band.wins / (band.wins + band.losses)) * 1000) / 10 
          : 0,
        detailedBands: band.detailedBands, // Internal detail available if needed
      }));
      
      // Calculate OVERALL win rate (all bands)
      const allWins = bands.reduce((sum, b) => sum + b.wins, 0);
      const allTotal = bands.reduce((sum, b) => sum + b.wins + b.losses, 0);
      const overallWinRate = allTotal > 0 
        ? Math.round((allWins / allTotal) * 1000) / 10 
        : 0;
      
      // Best performing band (for highlighting)
      const sortedBands = [...bands].filter(b => b.wins + b.losses >= 5).sort((a, b) => {
        const aRate = a.wins + a.losses > 0 ? a.wins / (a.wins + a.losses) : 0;
        const bRate = b.wins + b.losses > 0 ? b.wins / (b.wins + b.losses) : 0;
        return bRate - aRate;
      });
      const bestBand = sortedBands[0];
      const bestBandWinRate = bestBand && (bestBand.wins + bestBand.losses) > 0
        ? Math.round((bestBand.wins / (bestBand.wins + bestBand.losses)) * 1000) / 10
        : 0;
      
      // Calculate HIGH signal strength (A + B+ = 4+ signals)
      const highSignalBands = bands.filter(b => b.minSignals >= 4);
      const highSignalWins = highSignalBands.reduce((sum, b) => sum + b.wins, 0);
      const highSignalTotal = highSignalBands.reduce((sum, b) => sum + b.wins + b.losses, 0);
      const highSignalWinRate = highSignalTotal > 0 
        ? Math.round((highSignalWins / highSignalTotal) * 1000) / 10 
        : 0;
      
      // Calculate MEDIUM+ (3+ signals: A, B+, B)
      const mediumPlusBands = bands.filter(b => b.minSignals >= 3);
      const mediumPlusWins = mediumPlusBands.reduce((sum, b) => sum + b.wins, 0);
      const mediumPlusTotal = mediumPlusBands.reduce((sum, b) => sum + b.wins + b.losses, 0);
      const mediumPlusWinRate = mediumPlusTotal > 0 
        ? Math.round((mediumPlusWins / mediumPlusTotal) * 1000) / 10 
        : 0;
      
      res.json({
        calibratedWinRate: overallWinRate,
        calibratedTrades: allTotal,
        calibratedWins: allWins,
        overallWinRate,
        overallTrades: allTotal,
        overallWins: allWins,
        bestBand: bestBand?.name || 'N/A',
        bestBandWinRate,
        excludedLowConfidence: 0,
        confidenceBreakdown,
        // Signal strength comparison (renamed from confidence)
        highConfidence: {
          bands: 'A + B+ (4+ signals)',
          trades: highSignalTotal,
          wins: highSignalWins,
          losses: highSignalTotal - highSignalWins,
          winRate: highSignalWinRate,
        },
        mediumPlusConfidence: {
          bands: 'A + B+ + B (3+ signals)',
          trades: mediumPlusTotal,
          wins: mediumPlusWins,
          losses: mediumPlusTotal - mediumPlusWins,
          winRate: mediumPlusWinRate,
        },
        allConfidence: {
          bands: 'All Bands (A-D)',
          trades: allTotal,
          wins: allWins,
          losses: allTotal - allWins,
          winRate: overallWinRate,
        },
      });
    } catch (error) {
      logger.error("Signal strength stats error:", error);
      res.status(500).json({ error: "Failed to fetch signal strength stats" });
    }
  });

  // 🎯 TRUE CALIBRATION CURVE: Actual win rate for each confidence score
  // This is the DATA-DRIVEN calibration - shows what ACTUALLY happens at each confidence level
  // Use this to recalibrate future confidence scores so predicted = actual
  app.get("/api/performance/calibration-curve", async (req, res) => {
    try {
      const allIdeas = await storage.getAllTradeIdeas();
      
      // 🔧 DATA INTEGRITY: Use shared canonical filters for consistency (include Flow)
      const filteredIdeas = applyCanonicalPerformanceFilters(allIdeas, { includeFlowLotto: true });
      
      // Get decided trades only (wins + real losses, excludes breakeven and legacy engines)
      const resolvedIdeas = getDecidedTrades(filteredIdeas, { includeAllVersions: false });
      
      // Create 5-point confidence buckets (20-24, 25-29, 30-34, ..., 95-100)
      const buckets: Map<number, { wins: number; losses: number; totalPnL: number; trades: any[] }> = new Map();
      
      // Initialize buckets from 20 to 100 in 5-point increments
      for (let i = 20; i <= 100; i += 5) {
        buckets.set(i, { wins: 0, losses: 0, totalPnL: 0, trades: [] });
      }
      
      resolvedIdeas.forEach(idea => {
        const confidence = idea.confidenceScore || 0;
        // Round down to nearest 5 (e.g., 67 -> 65)
        const bucketKey = Math.max(20, Math.min(100, Math.floor(confidence / 5) * 5));
        
        const bucket = buckets.get(bucketKey);
        if (bucket) {
          const isWin = idea.outcomeStatus === 'hit_target';
          if (isWin) bucket.wins++;
          else bucket.losses++;
          bucket.totalPnL += idea.percentGain || 0;
          bucket.trades.push({
            symbol: idea.symbol,
            source: idea.source,
            confidence: idea.confidenceScore,
            outcome: idea.outcomeStatus,
            pnl: idea.percentGain
          });
        }
      });
      
      // Build calibration curve
      const calibrationCurve: {
        confidenceRange: string;
        midpoint: number;
        predicted: number; // What we said (midpoint of range)
        actual: number;    // What actually happened (win rate)
        trades: number;
        wins: number;
        losses: number;
        avgPnL: number;
        calibrationError: number; // How far off we were (predicted - actual)
        isCalibrated: boolean;    // Within 10% of prediction
      }[] = [];
      
      buckets.forEach((data, bucketStart) => {
        const totalTrades = data.wins + data.losses;
        if (totalTrades === 0) return; // Skip empty buckets
        
        const midpoint = bucketStart + 2.5; // e.g., 65-69 -> 67.5
        const actualWinRate = Math.round((data.wins / totalTrades) * 1000) / 10;
        const avgPnL = Math.round((data.totalPnL / totalTrades) * 10) / 10;
        const error = Math.round((midpoint - actualWinRate) * 10) / 10;
        
        calibrationCurve.push({
          confidenceRange: `${bucketStart}-${bucketStart + 4}`,
          midpoint,
          predicted: midpoint,
          actual: actualWinRate,
          trades: totalTrades,
          wins: data.wins,
          losses: data.losses,
          avgPnL,
          calibrationError: error,
          isCalibrated: Math.abs(error) <= 10
        });
      });
      
      // Sort by confidence range
      calibrationCurve.sort((a, b) => a.midpoint - b.midpoint);
      
      // Calculate overall calibration quality
      const totalError = calibrationCurve.reduce((sum, c) => sum + Math.abs(c.calibrationError), 0);
      const avgError = calibrationCurve.length > 0 ? Math.round(totalError / calibrationCurve.length * 10) / 10 : 0;
      const calibratedBuckets = calibrationCurve.filter(c => c.isCalibrated).length;
      const calibrationQuality = calibrationCurve.length > 0 
        ? Math.round((calibratedBuckets / calibrationCurve.length) * 100) 
        : 0;
      
      // Calculate Brier Score: Mean squared error between predicted probability and actual outcome
      // Lower is better: 0 = perfect, 0.25 = random guessing, 0.5 = inverse predictions
      let brierSum = 0;
      let brierCount = 0;
      resolvedIdeas.forEach(idea => {
        const predictedProb = (idea.confidenceScore || 50) / 100; // Convert to 0-1
        const actualOutcome = idea.outcomeStatus === 'hit_target' ? 1 : 0;
        brierSum += Math.pow(predictedProb - actualOutcome, 2);
        brierCount++;
      });
      const brierScore = brierCount > 0 ? Math.round((brierSum / brierCount) * 1000) / 1000 : 0;
      
      // Calculate Brier skill score (relative to baseline of just using overall win rate)
      const baselineWinRate = resolvedIdeas.filter(i => i.outcomeStatus === 'hit_target').length / resolvedIdeas.length;
      let baselineBrierSum = 0;
      resolvedIdeas.forEach(idea => {
        const actualOutcome = idea.outcomeStatus === 'hit_target' ? 1 : 0;
        baselineBrierSum += Math.pow(baselineWinRate - actualOutcome, 2);
      });
      const baselineBrier = brierCount > 0 ? baselineBrierSum / brierCount : 0;
      const brierSkillScore = baselineBrier > 0 ? Math.round((1 - brierScore / baselineBrier) * 1000) / 1000 : 0;
      
      res.json({
        calibrationCurve,
        summary: {
          totalTrades: resolvedIdeas.length,
          avgCalibrationError: avgError,
          calibratedBuckets,
          totalBuckets: calibrationCurve.length,
          calibrationQuality: `${calibrationQuality}%`,
          status: avgError <= 15 ? 'WELL_CALIBRATED' : avgError <= 25 ? 'NEEDS_ADJUSTMENT' : 'POORLY_CALIBRATED',
          brierScore,
          brierSkillScore,
          brierInterpretation: brierScore <= 0.15 ? 'Excellent' : brierScore <= 0.20 ? 'Good' : brierScore <= 0.25 ? 'Fair' : 'Poor'
        }
      });
    } catch (error) {
      logger.error("Calibration curve error:", error);
      res.status(500).json({ error: "Failed to generate calibration curve" });
    }
  });

  // 🎯 ACTUAL ENGINE PERFORMANCE - Verified from database with statistical rigor
  // Provides PROOF of engine win rates with confidence intervals, Sharpe ratios, and sample size grading
  app.get("/api/performance/engine-actual-stats", async (req, res) => {
    try {
      const allIdeas = await storage.getAllTradeIdeas();
      
      // Filter: only resolved trades (hit_target or hit_stop), excluding buggy data
      const resolvedIdeas = allIdeas.filter(idea => 
        (idea.outcomeStatus === 'hit_target' || idea.outcomeStatus === 'hit_stop') &&
        !idea.excludeFromTraining
      );
      
      // Statistical helper functions
      const calculateStdDev = (values: number[]): number => {
        if (values.length < 2) return 0;
        const mean = values.reduce((a, b) => a + b, 0) / values.length;
        const squaredDiffs = values.map(v => Math.pow(v - mean, 2));
        return Math.sqrt(squaredDiffs.reduce((a, b) => a + b, 0) / (values.length - 1));
      };
      
      // Wilson Score Interval - proper confidence interval for binomial proportions
      // More accurate than normal approximation, especially for small samples
      const calculateConfidenceInterval = (winRate: number, n: number, confidence: number = 0.95): { lower: number; upper: number } => {
        if (n < 2) return { lower: 0, upper: 100 };
        const z = confidence === 0.95 ? 1.96 : 2.576;
        const p = winRate / 100; // wins / n
        
        // Wilson score interval formula
        const denominator = 1 + (z * z) / n;
        const center = (p + (z * z) / (2 * n)) / denominator;
        const halfWidth = (z * Math.sqrt((p * (1 - p)) / n + (z * z) / (4 * n * n))) / denominator;
        
        return {
          lower: Math.max(0, Math.round((center - halfWidth) * 1000) / 10),
          upper: Math.min(100, Math.round((center + halfWidth) * 1000) / 10)
        };
      };
      
      const getSampleSizeGrade = (n: number): 'A' | 'B' | 'C' | 'D' | 'F' => {
        if (n >= 100) return 'A';
        if (n >= 50) return 'B';
        if (n >= 30) return 'C';
        if (n >= 10) return 'D';
        return 'F';
      };
      
      // Group by engine (source) with extended stats
      const engineStats = new Map<string, {
        engine: string;
        displayName: string;
        totalTrades: number;
        wins: number;
        losses: number;
        winRate: number;
        avgGain: number;
        totalGain: number;
        gains: number[];
        avgWin: number;
        avgLoss: number;
        winGains: number[];
        lossGains: number[];
        holdingDays: number[]; // per-trade holding periods in trading days
      }>();
      
      const engineDisplayNames: Record<string, string> = {
        'flow': 'Flow Scanner',
        'flow_scanner': 'Flow Scanner',
        'ai': 'AI Engine',
        'quant': 'Quant Engine',
        'hybrid': 'Hybrid',
        'chart_analysis': 'Chart Analysis',
        'lotto_scanner': 'Lotto Scanner',
        'manual': 'Manual',
      };
      
      // Outlier protection: clamp percent gains to ±50%
      const OUTLIER_MIN = -50;
      const OUTLIER_MAX = 50;
      
      resolvedIdeas.forEach(idea => {
        const engine = (idea.source || 'unknown').toLowerCase();
        const normalizedEngine = engine === 'flow_scanner' ? 'flow' : engine;
        
        if (!engineStats.has(normalizedEngine)) {
          engineStats.set(normalizedEngine, {
            engine: normalizedEngine,
            displayName: engineDisplayNames[normalizedEngine] || normalizedEngine.toUpperCase(),
            totalTrades: 0,
            wins: 0,
            losses: 0,
            winRate: 0,
            avgGain: 0,
            totalGain: 0,
            gains: [],
            avgWin: 0,
            avgLoss: 0,
            winGains: [],
            lossGains: [],
            holdingDays: [],
          });
        }
        
        const stats = engineStats.get(normalizedEngine)!;
        stats.totalTrades++;
        const clampedGain = Math.max(OUTLIER_MIN, Math.min(OUTLIER_MAX, idea.percentGain || 0));
        stats.gains.push(clampedGain);
        stats.totalGain += clampedGain;

        // Collect holding duration for time-weighted Sharpe calculation
        if (idea.actualHoldingTimeMinutes) {
          stats.holdingDays.push(idea.actualHoldingTimeMinutes / (60 * 6.5)); // 6.5hr trading day
        } else if (idea.timestamp && idea.exitDate) {
          const diffMs = new Date(idea.exitDate).getTime() - new Date(idea.timestamp).getTime();
          stats.holdingDays.push(Math.max(0.1, diffMs / (1000 * 60 * 60 * 6.5)));
        }

        if (idea.outcomeStatus === 'hit_target') {
          stats.wins++;
          stats.winGains.push(clampedGain);
        } else {
          stats.losses++;
          stats.lossGains.push(clampedGain);
        }
      });
      
      // Calculate final stats with statistical metrics
      const engines = Array.from(engineStats.values()).map(stats => {
        const winRate = stats.totalTrades > 0 ? (stats.wins / stats.totalTrades) * 100 : 0;
        const avgGain = stats.totalTrades > 0 ? stats.totalGain / stats.totalTrades : 0;
        const avgWin = stats.winGains.length > 0 ? stats.winGains.reduce((a, b) => a + b, 0) / stats.winGains.length : 0;
        const avgLoss = stats.lossGains.length > 0 ? Math.abs(stats.lossGains.reduce((a, b) => a + b, 0) / stats.lossGains.length) : 0;
        
        // Convert to log returns for proper Sharpe calculation
        const logReturns = stats.gains.map(g => Math.log(1 + g / 100));
        const meanLogReturn = logReturns.length > 0 ? logReturns.reduce((a, b) => a + b, 0) / logReturns.length : 0;
        const logReturnStdDev = calculateStdDev(logReturns);
        
        // Binomial confidence interval for win rate (95% CI using Wilson score)
        const ci = calculateConfidenceInterval(winRate, stats.totalTrades);
        
        // Profit Factor = Gross Wins / Gross Losses (correct P&L ratio)
        const grossWins = stats.winGains.reduce((a, b) => a + b, 0);
        const grossLosses = Math.abs(stats.lossGains.reduce((a, b) => a + b, 0));
        const profitFactor = grossLosses > 0 ? Math.round((grossWins / grossLosses) * 100) / 100 : grossWins > 0 ? Infinity : 0;
        
        // Expectancy = (WinRate * AvgWin) - (LossRate * AvgLoss)
        const expectancy = Math.round(((winRate / 100) * avgWin - ((100 - winRate) / 100) * avgLoss) * 100) / 100;
        
        // Annualized Sharpe Ratio with risk-free rate and duration-aware annualization
        // Formula: ((mean_excess) / std_excess) * sqrt(252 / avg_holding_days)
        // Risk-free: 4.5% annual (T-bill proxy), prorated per trade's holding period
        const MIN_SHARPE_SAMPLE = 30;
        const EPSILON = 0.0001;
        const ANNUAL_RISK_FREE = 0.045;
        const avgHoldingDays = stats.holdingDays.length > 0
          ? stats.holdingDays.reduce((a, b) => a + b, 0) / stats.holdingDays.length
          : 1; // default 1 trading day if no duration data available
        const riskFreePerTrade = (ANNUAL_RISK_FREE * avgHoldingDays) / 252;
        const excessLogReturns = logReturns.map(r => r - riskFreePerTrade);
        const meanExcessReturn = excessLogReturns.length > 0
          ? excessLogReturns.reduce((a, b) => a + b, 0) / excessLogReturns.length : 0;
        const excessStdDev = calculateStdDev(excessLogReturns);
        const annualizationFactor = Math.sqrt(252 / Math.max(avgHoldingDays, 0.1));
        const sharpeRatio = (stats.totalTrades >= MIN_SHARPE_SAMPLE && excessStdDev > EPSILON)
          ? Math.round(((meanExcessReturn / excessStdDev) * annualizationFactor) * 100) / 100
          : 0;
        const sharpeReliable = stats.totalTrades >= MIN_SHARPE_SAMPLE && excessStdDev > EPSILON;
        
        return {
          engine: stats.engine,
          displayName: stats.displayName,
          totalTrades: stats.totalTrades,
          wins: stats.wins,
          losses: stats.losses,
          winRate: Math.round(winRate * 10) / 10,
          avgGain: Math.round(avgGain * 100) / 100,
          avgWin: Math.round(avgWin * 100) / 100,
          avgLoss: Math.round(avgLoss * 100) / 100,
          stdDev: Math.round(logReturnStdDev * 10000) / 100, // Express as percentage
          confidenceInterval: ci,
          sampleSizeGrade: getSampleSizeGrade(stats.totalTrades),
          profitFactor: profitFactor === Infinity ? '∞' : profitFactor,
          expectancy,
          sharpeRatio,
          isStatisticallySignificant: stats.totalTrades >= 30,
        };
      });
      
      // Sort by win rate descending
      engines.sort((a, b) => b.winRate - a.winRate);
      
      // Calculate overall portfolio metrics using log returns
      // Annualized Sharpe with risk-free subtraction and duration-aware scaling
      const allLogReturns = resolvedIdeas.map(i => {
        const clampedGain = Math.max(OUTLIER_MIN, Math.min(OUTLIER_MAX, i.percentGain || 0));
        return Math.log(1 + clampedGain / 100);
      });
      const overallHoldingDays: number[] = [];
      resolvedIdeas.forEach(i => {
        if (i.actualHoldingTimeMinutes) {
          overallHoldingDays.push(i.actualHoldingTimeMinutes / (60 * 6.5));
        } else if (i.timestamp && i.exitDate) {
          const diffMs = new Date(i.exitDate).getTime() - new Date(i.timestamp).getTime();
          overallHoldingDays.push(Math.max(0.1, diffMs / (1000 * 60 * 60 * 6.5)));
        }
      });
      const overallAvgHoldingDays = overallHoldingDays.length > 0
        ? overallHoldingDays.reduce((a, b) => a + b, 0) / overallHoldingDays.length
        : 1;
      const overallRfPerTrade = (0.045 * overallAvgHoldingDays) / 252;
      const overallExcessReturns = allLogReturns.map(r => r - overallRfPerTrade);
      const overallMeanExcess = overallExcessReturns.length > 0
        ? overallExcessReturns.reduce((a, b) => a + b, 0) / overallExcessReturns.length : 0;
      const overallExcessStdDev = calculateStdDev(overallExcessReturns);
      const overallAnnFactor = Math.sqrt(252 / Math.max(overallAvgHoldingDays, 0.1));
      const overallSharpe = overallExcessStdDev > 0
        ? Math.round(((overallMeanExcess / overallExcessStdDev) * overallAnnFactor) * 100) / 100
        : 0;
      
      // Calculate drawdown using multiplicative equity curve: Π(1 + r_i)
      let equity = 1.0; // Start with $1
      let peakEquity = 1.0;
      let maxDrawdown = 0;
      resolvedIdeas
        .sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime())
        .forEach(idea => {
          const gain = Math.max(OUTLIER_MIN, Math.min(OUTLIER_MAX, idea.percentGain || 0));
          equity *= (1 + gain / 100); // Multiplicative return
          if (equity > peakEquity) peakEquity = equity;
          const drawdown = (peakEquity - equity) / peakEquity; // Percentage drawdown from peak
          if (drawdown > maxDrawdown) maxDrawdown = drawdown;
        });
      
      res.json({
        engines,
        summary: {
          totalResolvedTrades: resolvedIdeas.length,
          bestEngine: engines[0]?.displayName || 'N/A',
          bestWinRate: engines[0]?.winRate || 0,
          worstEngine: engines[engines.length - 1]?.displayName || 'N/A',
          worstWinRate: engines[engines.length - 1]?.winRate || 0,
          overallSharpeRatio: overallSharpe,
          maxDrawdown: Math.round(maxDrawdown * 10000) / 100, // Convert 0-1 to percentage
          lastUpdated: new Date().toISOString(),
        }
      });
    } catch (error) {
      logger.error("Engine actual stats error:", error);
      res.status(500).json({ error: "Failed to fetch engine stats" });
    }
  });

  // 📈 ROLLING WIN RATE - Performance trends over time
  app.get("/api/performance/rolling-win-rate", async (req, res) => {
    try {
      const windowSize = parseInt(req.query.window as string) || 20;
      const engine = req.query.engine as string | undefined;
      
      const allIdeas = await storage.getAllTradeIdeas();
      
      // Filter resolved trades
      let resolvedIdeas = allIdeas.filter(idea => 
        idea.outcomeStatus === 'hit_target' || idea.outcomeStatus === 'hit_stop'
      );
      
      // Optional engine filter
      if (engine) {
        resolvedIdeas = resolvedIdeas.filter(idea => 
          (idea.source || '').toLowerCase() === engine.toLowerCase()
        );
      }
      
      // Sort by timestamp ascending
      resolvedIdeas.sort((a, b) => 
        new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime()
      );
      
      if (resolvedIdeas.length < windowSize) {
        return res.json({
          rollingData: [],
          summary: {
            totalTrades: resolvedIdeas.length,
            windowSize,
            insufficientData: true,
            message: `Need at least ${windowSize} trades for rolling analysis`
          }
        });
      }
      
      // Calculate rolling win rates
      const rollingData: { 
        tradeIndex: number; 
        date: string;
        winRate: number; 
        cumulativeWinRate: number;
        avgPnL: number;
        wins: number;
        losses: number;
      }[] = [];
      
      let cumulativeWins = 0;
      let cumulativeLosses = 0;
      
      for (let i = 0; i < resolvedIdeas.length; i++) {
        const isWin = resolvedIdeas[i].outcomeStatus === 'hit_target';
        if (isWin) cumulativeWins++;
        else cumulativeLosses++;
        
        if (i >= windowSize - 1) {
          // Calculate window stats
          const windowStart = i - windowSize + 1;
          const windowTrades = resolvedIdeas.slice(windowStart, i + 1);
          const windowWins = windowTrades.filter(t => t.outcomeStatus === 'hit_target').length;
          const windowLosses = windowSize - windowWins;
          const windowWinRate = Math.round((windowWins / windowSize) * 1000) / 10;
          const cumulativeWinRate = Math.round((cumulativeWins / (i + 1)) * 1000) / 10;
          
          // Calculate average P&L for window
          const windowPnL = windowTrades.reduce((sum, t) => 
            sum + Math.max(-50, Math.min(50, t.percentGain || 0)), 0
          );
          const avgPnL = Math.round((windowPnL / windowSize) * 100) / 100;
          
          rollingData.push({
            tradeIndex: i + 1,
            date: new Date(resolvedIdeas[i].timestamp).toISOString().split('T')[0],
            winRate: windowWinRate,
            cumulativeWinRate,
            avgPnL,
            wins: windowWins,
            losses: windowLosses,
          });
        }
      }
      
      // Calculate trend (last 20 vs first 20 datapoints)
      let trend = 'stable';
      if (rollingData.length >= 40) {
        const firstAvg = rollingData.slice(0, 20).reduce((s, d) => s + d.winRate, 0) / 20;
        const lastAvg = rollingData.slice(-20).reduce((s, d) => s + d.winRate, 0) / 20;
        if (lastAvg - firstAvg > 5) trend = 'improving';
        else if (firstAvg - lastAvg > 5) trend = 'declining';
      }
      
      // Find peaks and troughs
      const winRates = rollingData.map(d => d.winRate);
      const maxWinRate = Math.max(...winRates);
      const minWinRate = Math.min(...winRates);
      const currentWinRate = winRates[winRates.length - 1] || 0;
      
      res.json({
        rollingData,
        summary: {
          totalTrades: resolvedIdeas.length,
          windowSize,
          trend,
          currentWinRate,
          maxWinRate,
          minWinRate,
          volatility: Math.round((maxWinRate - minWinRate) * 10) / 10,
        }
      });
    } catch (error) {
      logger.error("Rolling win rate error:", error);
      res.status(500).json({ error: "Failed to calculate rolling win rate" });
    }
  });

  // 📉 DRAWDOWN ANALYSIS - Peak-to-trough metrics
  app.get("/api/performance/drawdown-analysis", requireTier('canAccessDrawdownAnalysis'), async (req, res) => {
    try {
      const allIdeas = await storage.getAllTradeIdeas();
      
      // Filter resolved trades
      const resolvedIdeas = allIdeas.filter(idea => 
        idea.outcomeStatus === 'hit_target' || idea.outcomeStatus === 'hit_stop'
      );
      
      // Sort by timestamp ascending
      resolvedIdeas.sort((a, b) => 
        new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime()
      );
      
      // Outlier protection
      const OUTLIER_MIN = -50;
      const OUTLIER_MAX = 50;
      
      // Calculate MULTIPLICATIVE equity curve: Π(1 + r_i)
      // This is the correct way to compound returns
      const equityCurve: { 
        tradeIndex: number;
        date: string;
        equity: number;        // Multiplicative equity (starts at 1.0)
        peak: number;
        drawdown: number;      // Absolute drawdown from peak
        drawdownPercent: number; // Percentage drawdown from peak
      }[] = [];
      
      let equity = 1.0; // Start with $1 normalized
      let peakEquity = 1.0;
      let maxDrawdownPercent = 0;
      let maxDrawdownStart = 0;
      let maxDrawdownEnd = 0;
      let currentDrawdownStart = 0;
      let inDrawdown = false;
      
      // Track all drawdown periods
      const drawdownPeriods: {
        start: number;
        end: number;
        depth: number;
        recoveryTrades: number;
      }[] = [];
      
      resolvedIdeas.forEach((idea, i) => {
        const gain = Math.max(OUTLIER_MIN, Math.min(OUTLIER_MAX, idea.percentGain || 0));
        equity *= (1 + gain / 100); // Multiplicative return
        
        if (equity > peakEquity) {
          // New peak - record recovery if we were in drawdown
          if (inDrawdown && currentDrawdownStart > 0) {
            const troughEquity = Math.min(...equityCurve.slice(currentDrawdownStart, i + 1).map(e => e.equity));
            drawdownPeriods.push({
              start: currentDrawdownStart,
              end: i,
              depth: ((peakEquity - troughEquity) / peakEquity) * 100, // Percentage depth
              recoveryTrades: i - currentDrawdownStart
            });
          }
          peakEquity = equity;
          inDrawdown = false;
        } else if (equity < peakEquity) {
          if (!inDrawdown) {
            currentDrawdownStart = i;
            inDrawdown = true;
          }
        }
        
        const drawdownAbs = peakEquity - equity;
        const drawdownPercent = (drawdownAbs / peakEquity) * 100;
        
        if (drawdownPercent > maxDrawdownPercent) {
          maxDrawdownPercent = drawdownPercent;
          maxDrawdownEnd = i;
        }
        
        equityCurve.push({
          tradeIndex: i + 1,
          date: new Date(idea.timestamp).toISOString().split('T')[0],
          equity: Math.round(equity * 10000) / 10000, // 4 decimal places
          peak: Math.round(peakEquity * 10000) / 10000,
          drawdown: Math.round(drawdownAbs * 10000) / 10000,
          drawdownPercent: Math.round(drawdownPercent * 10) / 10,
        });
      });
      
      // Current drawdown (from equity curve)
      const currentDrawdownValue = equityCurve.length > 0 ? equityCurve[equityCurve.length - 1].drawdown : 0;
      const currentDrawdownPercentValue = equityCurve.length > 0 ? equityCurve[equityCurve.length - 1].drawdownPercent : 0;
      
      // Average recovery time
      const avgRecoveryTrades = drawdownPeriods.length > 0 
        ? Math.round(drawdownPeriods.reduce((s, d) => s + d.recoveryTrades, 0) / drawdownPeriods.length)
        : 0;
      
      // Total return as percentage: (final equity - 1) * 100
      const finalEquity = equityCurve.length > 0 ? equityCurve[equityCurve.length - 1].equity : 1;
      const totalReturnPercent = (finalEquity - 1) * 100;
      
      // Calmar Ratio = Annualized Return / Max Drawdown (industry standard)
      // Returns structured object with value and status for explicit handling
      const TRADES_PER_YEAR_FALLBACK = 100;
      const MIN_TRADES_FOR_CALMAR = 10;
      
      let annualizedReturnDecimal = 0;
      let observationYears = 0;
      let timestampsValid = false;
      
      if (resolvedIdeas.length >= 2) {
        const sortedTrades = [...resolvedIdeas].sort((a, b) => 
          new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime()
        );
        const firstTradeTime = new Date(sortedTrades[0].timestamp).getTime();
        const lastTradeTime = new Date(sortedTrades[sortedTrades.length - 1].timestamp).getTime();
        
        if (!isNaN(firstTradeTime) && !isNaN(lastTradeTime) && lastTradeTime > firstTradeTime) {
          const msPerYear = 365.25 * 24 * 60 * 60 * 1000;
          observationYears = (lastTradeTime - firstTradeTime) / msPerYear;
          timestampsValid = true;
        } else {
          observationYears = resolvedIdeas.length / TRADES_PER_YEAR_FALLBACK;
        }
        
        if (observationYears > 0) {
          annualizedReturnDecimal = Math.pow(finalEquity, 1 / observationYears) - 1;
        }
      } else if (resolvedIdeas.length === 1) {
        observationYears = 1 / TRADES_PER_YEAR_FALLBACK;
        annualizedReturnDecimal = Math.pow(finalEquity, 1 / observationYears) - 1;
      }
      
      const maxDrawdownDecimal = maxDrawdownPercent / 100;
      
      // Determine Calmar status with explicit states
      type CalmarStatus = 'valid' | 'estimated' | 'insufficient-sample' | 'no-drawdown';
      let calmarStatus: CalmarStatus;
      let calmarValue: number | null = null;
      
      if (resolvedIdeas.length < MIN_TRADES_FOR_CALMAR) {
        calmarStatus = 'insufficient-sample';
      } else if (maxDrawdownDecimal <= 0) {
        calmarStatus = 'no-drawdown';
      } else if (!timestampsValid) {
        calmarStatus = 'estimated';
        calmarValue = Math.round((annualizedReturnDecimal / maxDrawdownDecimal) * 100) / 100;
      } else {
        calmarStatus = 'valid';
        calmarValue = Math.round((annualizedReturnDecimal / maxDrawdownDecimal) * 100) / 100;
      }
      
      res.json({
        equityCurve,
        drawdownPeriods: drawdownPeriods.slice(-10), // Last 10 drawdown periods
        summary: {
          totalTrades: resolvedIdeas.length,
          totalReturnPercent: Math.round(totalReturnPercent * 100) / 100,
          maxDrawdownPercent: Math.round(maxDrawdownPercent * 10) / 10,
          currentDrawdownPercent: Math.round(currentDrawdownPercentValue * 10) / 10,
          isInDrawdown: currentDrawdownPercentValue > 0,
          totalDrawdownPeriods: drawdownPeriods.length,
          avgRecoveryTrades,
          calmar: {
            value: calmarValue,
            status: calmarStatus,
          },
          annualizedReturnPercent: Math.round(annualizedReturnDecimal * 10000) / 100,
          observationYears: Math.round(observationYears * 100) / 100,
          finalEquity: Math.round(finalEquity * 10000) / 10000,
        }
      });
    } catch (error) {
      logger.error("Drawdown analysis error:", error);
      res.status(500).json({ error: "Failed to calculate drawdown analysis" });
    }
  });

