  // =============================================
  // LIQUID-NAME REVERSAL PUBLISHER
  // =============================================
  // Unlike the index-only session scanner, this watches liquid single names
  // (including TSLA) and writes only a CONFIRMED VWAP reversal with a real,
  // liquid same-day CBOE contract. The endpoint accepts no arbitrary ticker
  // universe, so it cannot be used to turn the scanner into a quote hammer.
  app.get("/api/scanner/liquid-reversals/status", async (_req, res) => {
    const { isLiquidReversalSession, LIQUID_REVERSAL_UNIVERSE } = await import('./liquid-reversal-publisher');
    res.json({
      marketOpen: isLiquidReversalSession(),
      cadence: '5m during 10:00–15:15 ET weekdays',
      universe: LIQUID_REVERSAL_UNIVERSE,
      contractRule: 'same-day CBOE bid + ask, <=20% spread, OI >=100 or volume >=25',
      confirmationRule: 'VWAP reclaim/rejection + 5m follow-through + RSI + volume context',
    });
  });

  app.post("/api/scanner/liquid-reversals/run", marketDataLimiter, async (req, res) => {
    try {
      const { LIQUID_REVERSAL_UNIVERSE, runLiquidReversalPublisher } = await import('./liquid-reversal-publisher');
      const requested = Array.isArray(req.body?.symbols)
        ? req.body.symbols.map((value: unknown) => String(value).toUpperCase())
        : LIQUID_REVERSAL_UNIVERSE;
      const allowed = requested.filter((symbol: string) => (LIQUID_REVERSAL_UNIVERSE as readonly string[]).includes(symbol));
      if (!allowed.length) {
        return res.status(400).json({ error: `Symbols must be in the liquid reversal universe: ${LIQUID_REVERSAL_UNIVERSE.join(', ')}` });
      }
      const result = await runLiquidReversalPublisher(allowed);
      res.json(result);
    } catch (error: any) {
      logger.error('[LIQUID-REVERSAL] manual scan failed:', error);
      res.status(500).json({ error: error?.message || 'Liquid reversal scan failed' });
    }
  });

  // Real two-leg quote plan for an existing directional thesis. This remains a
  // planner until spread legs are first-class persisted position fields; storing
  // only the long leg as a "signal" would lie about both max loss and payoff.
  app.get("/api/options/debit-spread/:symbol", marketDataLimiter, async (req, res) => {
    try {
      const symbol = String(req.params.symbol || '').toUpperCase();
      const direction = String(req.query.direction || 'long').toLowerCase();
      if (!/^[A-Z.]{1,10}$/.test(symbol) || (direction !== 'long' && direction !== 'short')) {
        return res.status(400).json({ error: 'Use a valid symbol and direction=long|short.' });
      }
      const targetRaw = Number(req.query.target);
      const minDte = Number(req.query.minDte);
      const maxDte = Number(req.query.maxDte);
      const maxRisk = Number(req.query.maxRisk);
      const { planDebitSpread } = await import('./debit-spread-planner');
      const plan = await planDebitSpread({
        symbol,
        direction: direction as 'long' | 'short',
        targetPrice: Number.isFinite(targetRaw) && targetRaw > 0 ? targetRaw : null,
        minDte: Number.isFinite(minDte) && minDte > 0 ? minDte : undefined,
        maxDte: Number.isFinite(maxDte) && maxDte > 0 ? maxDte : undefined,
        maxRiskDollars: Number.isFinite(maxRisk) && maxRisk > 0 ? maxRisk : undefined,
      });
      if (!plan) return res.status(404).json({ error: 'No liquid debit spread found from the delayed CBOE chain.' });
      res.json(plan);
    } catch (error: any) {
      logger.error('[DEBIT-SPREAD] planner failed:', error);
      res.status(500).json({ error: error?.message || 'Debit spread planning failed' });
    }
  });

  // =============================================
  // SPX COMMAND CENTER - Aggregated Dashboard
  // =============================================

  app.get("/api/spx/dashboard", async (req, res) => {
    try {
      const validSymbols = ['SPY', 'QQQ', 'IWM', 'SPX'];
      const symbolParam = ((req.query.symbol as string) || '').toUpperCase();
      const activeSymbol = validSymbols.includes(symbolParam) ? symbolParam : '';

      // Gather all index data in parallel
      const [orbModule, sessionModule, lottoModule, swingModule] = await Promise.all([
        import("./spx-orb-scanner"),
        import("./spx-session-scanner"),
        import("./index-lotto-scanner"),
        import("./spx-swing-catcher"),
      ]);

      const [orbStatus, activeBreakouts, ranges, sessionSignals, sessionLevels, lottoResult, swingAlerts, swingStatus] =
        await Promise.all([
          orbModule.getORBStatus(),
          orbModule.getActiveBreakouts(),
          orbModule.getRanges(),
          sessionModule.getActiveSignals(),
          sessionModule.getLevels(),
          lottoModule.scanIndexLottoPlays().catch(() => ({ indexData: [], lottoPlays: [] })),
          Promise.resolve(swingModule.getActiveSwingAlerts()),
          Promise.resolve(swingModule.getSwingCatcherStatus()),
        ]);

      // Filter by symbol if specified
      const matchSymbol = (s: string) =>
        !activeSymbol || s === activeSymbol || (activeSymbol === 'SPX' && s === 'SPY');

      const filteredBreakouts = activeSymbol
        ? activeBreakouts.filter((b: any) => matchSymbol(b.symbol))
        : activeBreakouts;

      const filteredRanges = activeSymbol
        ? ranges.filter((r: any) => matchSymbol(r.symbol))
        : ranges;

      const filteredSignals = activeSymbol
        ? sessionSignals.filter((s: any) => matchSymbol(s.symbol))
        : sessionSignals;

      const filteredLevels = activeSymbol
        ? sessionLevels.filter((l: any) => matchSymbol(l.symbol))
        : sessionLevels;

      const filteredLottos = activeSymbol
        ? (lottoResult.lottoPlays || []).filter((p: any) => matchSymbol(p.underlying))
        : (lottoResult.lottoPlays || []);

      const filteredIndexData = activeSymbol
        ? (lottoResult.indexData || []).filter((d: any) => matchSymbol(d.symbol))
        : (lottoResult.indexData || []);

      // Get today's trade ideas from DB
      const allIdeas = await storage.getAllTradeIdeas();
      const now = new Date();
      const nowET = new Date(now.toLocaleString('en-US', { timeZone: 'America/New_York' }));
      const todayStrET = `${nowET.getFullYear()}-${String(nowET.getMonth() + 1).padStart(2, '0')}-${String(nowET.getDate()).padStart(2, '0')}`;

      const spxIdeasRaw = allIdeas.filter((idea: any) => {
        const ideaTime = new Date(idea.timestamp);
        const ideaDateStrET = ideaTime.toLocaleDateString('en-CA', { timeZone: 'America/New_York' });
        if (ideaDateStrET !== todayStrET) return false;
        const isIndexIdea = idea.source === 'orb_scanner' ||
          idea.source === 'spx_session' ||
          idea.source === 'swing_catcher' ||
          ['SPX', 'SPY', 'QQQ', 'IWM'].includes(idea.symbol);
        if (!isIndexIdea) return false;
        return activeSymbol ? matchSymbol(idea.symbol) : true;
      });
      // Dedup by symbol:direction:source — keep most recent
      const dedupMap = new Map<string, any>();
      for (const idea of spxIdeasRaw.sort((a: any, b: any) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())) {
        const key = `${idea.symbol}:${idea.direction}:${idea.dataSourceUsed || idea.source || ''}`;
        if (!dedupMap.has(key)) dedupMap.set(key, idea);
      }
      const spxIdeas = Array.from(dedupMap.values()).slice(0, 25);

      res.json({
        timestamp: new Date().toISOString(),
        symbol: activeSymbol || 'ALL',
        orbScanner: {
          ...orbStatus,
          breakouts: filteredBreakouts,
          ranges: filteredRanges,
        },
        sessionScanner: {
          signals: filteredSignals,
          levels: filteredLevels,
        },
        swingCatcher: {
          ...swingStatus,
          alerts: swingAlerts,
        },
        indexData: filteredIndexData,
        lottoPlays: filteredLottos,
        todayIdeas: spxIdeas,
        todayIdeasCount: spxIdeas.length,
      });
    } catch (error: any) {
      logger.error('[SPX-DASHBOARD] Error:', error);
      res.status(500).json({ error: error?.message || "SPX dashboard failed" });
    }
  });

