      const alertSymbols = new Set(alertCandidates.map(c => c.symbol));
      const mergedCandidates = [
        ...alertCandidates,
        ...discoveredCandidates.filter(c => !alertSymbols.has(c.symbol))
      ].sort((a, b) => b.score - a.score);

