  // ─── Weekly Path Projection ──────────────────────────────────
    app.get("/api/weekly-path/:symbol", requireBetaAccess, async (req: any, res) => {
    try {
      const symbol = req.params.symbol.toUpperCase();

      const { calculateAggregateGammaExposure } = await import('./gamma-exposure');
      const { toSnapshot } = await import('./gex-vex-scanner');
      const { computeWeeklyPath } = await import('./weekly-path-model');

      const { computeGEXFromCBOE } = await import('./gex-cboe-fallback');

      // Same source chain as the GEX terminal: Tradier → CBOE → last good
      // projection (stamped with its age — never passed off as current).
      let gex = await calculateAggregateGammaExposure(symbol);
      if (!gex) {
        const cboeSnapshot = await computeGEXFromCBOE(symbol);
        if (cboeSnapshot) gex = { snapshot: cboeSnapshot, dataQuality: 'cboe_fallback' } as any;
      }
      if (!gex) {
        const cached = loadLastGood('weekly-path', symbol);
        if (cached && Date.now() - cached.cachedAt < 24 * 3600_000) {
          return res.json({ ...cached.data, cached: true, cachedAt: new Date(cached.cachedAt).toISOString() });
        }
        return res.status(503).json({
          error: `Options data unavailable for ${symbol}`,
          reason: 'All data sources failed (Tradier, CBOE). Market may be closed or API keys may need renewal.',
          symbol,
        });
      }

      const snapshot = toSnapshot(gex);
      // Size the week with the market's own implied vol: VIX for the S&P
      // complex; everything else falls back to a stamped regime estimate.
      // Size the week on how far the symbol has ACTUALLY been moving (20-day
      // realized vol); VIX rides along for the S&P complex as the implied
      // reference. Implied usually exceeds realized, so it is not the sizer.
      let vol: { annualVol: number; source: 'realized-20d' | 'vix'; impliedVol?: number } | undefined;
      let impliedVol: number | undefined;
      if (['SPY', 'SPX', 'ES', 'VOO', 'IVV'].includes(symbol)) {
        const { getVixLevel } = await import('./market-pulse');
        const vix = await getVixLevel().catch(() => null);
        if (vix) impliedVol = vix / 100;
      }
      const closes = await fetchHistoricalPrices(symbol === 'SPX' ? 'SPY' : symbol, 'stock', 25).catch(() => [] as number[]);
      if (closes.length >= 21) {
        const rets = closes.slice(-21).slice(1).map((c, i, arr) => Math.log(c / closes.slice(-21)[i]));
        const mean = rets.reduce((a, b) => a + b, 0) / rets.length;
        const sd = Math.sqrt(rets.reduce((a, b) => a + (b - mean) ** 2, 0) / (rets.length - 1));
        const realized = sd * Math.sqrt(252);
        if (realized > 0.02 && realized < 1.5) vol = { annualVol: realized, source: 'realized-20d', impliedVol };
      }
      if (!vol && impliedVol) vol = { annualVol: impliedVol, source: 'vix', impliedVol };
      const projection = computeWeeklyPath(snapshot, vol);
      saveLastGood('weekly-path', symbol, projection);

      res.json(projection);
    } catch (error: any) {
      logger.error(`[WEEKLY-PATH] Error for ${req.params.symbol}:`, error);
      res.status(500).json({ error: "Failed to compute weekly path projection" });
    }
  });

  // ─── Multi-Signal Discovery Engine ──────────────────────────
